var EXAMS_BASE = [{"id": "2027-g6-p1-quiz", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Quiz — Atletismo: pruebas y movimientos básicos (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "¿Qué es el atletismo?", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El atletismo es conocido como el «deporte base» porque reúne los movimientos naturales del ser humano: correr, saltar y lanzar. Sus pruebas se dividen en dos grandes grupos. Las pruebas de pista se realizan sobre un óvalo de 400 metros dividido en carriles: allí están las carreras de velocidad (100, 200 y 400 metros), las de medio fondo y fondo (800, 1500, 5000 metros y más), las carreras con vallas y los relevos. Las pruebas de campo se realizan en zonas especiales: los saltos (largo, triple, alto y con garrocha) y los lanzamientos (bala, disco, jabalina y martillo).<br><br>Para practicar atletismo no basta con tener fuerza o velocidad. El cuerpo necesita coordinación, es decir, que brazos, piernas y tronco se muevan de forma ordenada; equilibrio, para no perder el control al apoyar el pie o al caer de un salto; y una buena postura, que permite usar la energía sin desperdiciarla. Por eso, en las primeras clases se trabaja con juegos de carrera, saltos sobre aros y lanzamientos de pelotas pequeñas, antes de usar implementos oficiales. Antes de cualquier práctica se realiza un calentamiento que prepara músculos y articulaciones y disminuye el riesgo de lesiones."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el atletismo se llama «deporte base» porque:", "opciones": {"A": "es el deporte más antiguo de los Juegos Olímpicos.", "B": "reúne los movimientos naturales de correr, saltar y lanzar.", "C": "se practica únicamente en pistas de 400 metros.", "D": "no necesita ningún tipo de calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál de las siguientes es una prueba de campo?", "opciones": {"A": "Los relevos.", "B": "El salto largo.", "C": "Los 100 metros planos.", "D": "Los 1500 metros."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "La pista oficial de atletismo tiene una vuelta de:", "opciones": {"A": "100 metros.", "B": "1000 metros.", "C": "200 metros.", "D": "400 metros."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «coordinación» significa:", "opciones": {"A": "que brazos, piernas y tronco se muevan de forma ordenada.", "B": "que el cuerpo permanezca quieto antes de la salida.", "C": "que el atleta corra siempre a la máxima velocidad.", "D": "que el atleta use implementos oficiales desde la primera clase."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en las primeras clases se usan aros y pelotas pequeñas en lugar de implementos oficiales?", "opciones": {"A": "Porque las pelotas pequeñas pesan más que una bala oficial.", "B": "Porque el atletismo escolar no tiene pruebas de lanzamiento.", "C": "Porque primero se aprende el movimiento con materiales más fáciles y seguros.", "D": "Porque los implementos oficiales están prohibidos en los colegios."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante cae desequilibrado cada vez que termina un salto. ¿Qué capacidad necesita reforzar principalmente?", "opciones": {"A": "El equilibrio.", "B": "La velocidad de reacción.", "C": "La fuerza de los brazos.", "D": "La resistencia aeróbica."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "Las carreras de 100, 200 y 400 metros pertenecen al grupo de:", "opciones": {"A": "velocidad.", "B": "saltos.", "C": "lanzamientos.", "D": "fondo."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, una buena postura ayuda al atleta porque:", "opciones": {"A": "le evita entrenar la coordinación.", "B": "le permite usar la energía sin desperdiciarla.", "C": "reemplaza el calentamiento.", "D": "lo hace más alto que sus compañeros."}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de una práctica de carreras, lo más adecuado es:", "opciones": {"A": "estirar solo después de terminar la carrera.", "B": "correr de inmediato a máxima velocidad.", "C": "saltar en un pie durante diez minutos sin parar.", "D": "hacer un calentamiento que prepare músculos y articulaciones."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "El atletismo solo es para personas con mucha fuerza.", "B": "Las pruebas de campo son más importantes que las de pista.", "C": "El atletismo reúne movimientos básicos que requieren coordinación, equilibrio y postura.", "D": "El calentamiento es la parte más larga de una clase."}}], "modalidad": "Quiz"}, {"id": "2027-g6-p1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Atletismo: postura, coordinación y equilibrio (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "La postura y la técnica de carrera", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Correr parece sencillo, pero una buena técnica marca la diferencia. El tronco debe ir erguido y ligeramente inclinado hacia adelante, sin encorvar la espalda. La cabeza se mantiene alineada con el tronco y la mirada al frente, no hacia el suelo. Los brazos se doblan aproximadamente en ángulo recto (90 grados) y se mueven de adelante hacia atrás, al lado del cuerpo, en sentido contrario a las piernas: cuando avanza la pierna derecha, avanza el brazo izquierdo. Este movimiento cruzado se llama coordinación contralateral y ayuda a mantener el equilibrio.<br><br>En las carreras de velocidad, el pie apoya primero con la parte delantera (el metatarso) y no con el talón, lo que permite impulsarse más rápido. La rodilla sube al frente y el pie de atrás empuja el suelo con fuerza. Los hombros deben ir relajados: la tensión en el cuello y en las manos gasta energía y hace la carrera más lenta. Un error frecuente es mover los brazos cruzándolos delante del pecho, lo que hace girar el tronco y desvía la dirección."}, {"id": 2, "titulo": "La salida y la ubicación en el espacio", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "En las carreras de velocidad la salida es decisiva. Los atletas usan la salida baja, apoyando los pies en unos bloques llamados tacos de salida. El juez da tres señales: «¡A sus puestos!», cuando el atleta se ubica con las manos detrás de la línea; «¡Listos!», cuando eleva la cadera y queda inmóvil; y el disparo, que indica el inicio. Si un atleta sale antes del disparo comete una salida en falso, y según el reglamento internacional queda descalificado.<br><br>Cada corredor debe permanecer en su carril durante las pruebas de 100 metros. En la curva, los carriles exteriores parecen ir adelante; en realidad, esa ventaja compensa la mayor distancia que deben recorrer, y por eso las salidas están escalonadas. Ubicarse bien en el espacio y en el tiempo —saber dónde está el carril, cuándo acelerar y cuándo mantener la velocidad— es tan importante como la fuerza de las piernas. A esta habilidad se le llama ubicación espacio-temporal."}, {"id": 3, "titulo": "El salto largo: equilibrio en el aire y en la caída", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "El salto largo tiene cuatro fases: la carrera de impulso, la batida, el vuelo y la caída. En la carrera de impulso el atleta acelera de forma progresiva para llegar a la tabla de batida con la máxima velocidad que pueda controlar. La batida se hace con un solo pie, sin pisar más allá de la línea; si la pisa o la sobrepasa, el salto es nulo. Durante el vuelo, los brazos ayudan a mantener el equilibrio y a llevar las piernas hacia adelante. En la caída, el atleta flexiona las rodillas para amortiguar el impacto y lleva el cuerpo hacia adelante para no caer sentado hacia atrás.<br><br>La marca se mide desde la línea de batida hasta la huella más cercana que deja el cuerpo en la arena. Por eso, si el atleta apoya una mano detrás de los pies al caer, pierde distancia. El salto largo exige coordinar velocidad, fuerza y equilibrio en pocos segundos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, durante la carrera los brazos deben:", "opciones": {"A": "cruzarse delante del pecho en cada paso.", "B": "permanecer quietos para no gastar energía.", "C": "moverse de adelante hacia atrás, al lado del cuerpo.", "D": "moverse hacia arriba y hacia abajo por encima de la cabeza."}}, {"n": 2, "seccion": 1, "competencia": "Lexical", "enunciado": "La expresión «coordinación contralateral» se refiere a:", "opciones": {"A": "mover los dos brazos al mismo tiempo hacia adelante.", "B": "alternar carreras rápidas y lentas en una misma prueba.", "C": "correr siempre por el lado izquierdo de la pista.", "D": "mover el brazo de un lado al mismo tiempo que la pierna del lado contrario."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "En las carreras de velocidad, el pie apoya primero con:", "opciones": {"A": "el talón.", "B": "la parte delantera del pie (metatarso).", "C": "el borde externo del pie.", "D": "toda la planta al mismo tiempo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué cruzar los brazos delante del pecho es un error?", "opciones": {"A": "Porque está prohibido por el reglamento.", "B": "Porque hace girar el tronco y desvía la dirección de la carrera.", "C": "Porque obliga a apoyar el talón.", "D": "Porque impide respirar durante la carrera."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero corre con los hombros tensos y las manos apretadas. ¿Qué le recomendarías?", "opciones": {"A": "Relajar hombros y manos para no gastar energía de más.", "B": "Correr con los brazos estirados.", "C": "Apretar más fuerte para ganar velocidad.", "D": "Mirar al suelo para concentrarse."}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "¿Hacia dónde debe dirigirse la mirada durante la carrera?", "opciones": {"A": "Hacia los corredores de los lados.", "B": "Al frente.", "C": "Hacia el cielo.", "D": "Al suelo, cerca de los pies."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál enunciado resume mejor el primer texto?", "opciones": {"A": "Correr rápido depende solo de la fuerza de las piernas.", "B": "La técnica de carrera solo importa en las pruebas largas.", "C": "Una buena postura y el movimiento correcto de brazos y piernas hacen la carrera más eficiente.", "D": "Los brazos no influyen en la velocidad de un atleta."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es el orden correcto de las señales del juez en la salida?", "opciones": {"A": "«¡Ya!», «¡Listos!» y «¡Fuera!».", "B": "«¡Listos!», «¡A sus puestos!» y el disparo.", "C": "«¡A sus puestos!», «¡Listos!» y el disparo.", "D": "El disparo, «¡Listos!» y «¡A sus puestos!»."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Según el texto, un atleta que sale antes del disparo:", "opciones": {"A": "queda descalificado.", "B": "recibe una advertencia y repite la salida.", "C": "debe salir desde el último carril.", "D": "pierde un segundo en su tiempo final."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "Las salidas escalonadas en las carreras con curva existen porque:", "opciones": {"A": "así el público puede ver mejor la carrera.", "B": "el juez necesita más espacio para dar las señales.", "C": "los atletas más rápidos se ubican adelante.", "D": "los carriles exteriores recorren más distancia en la curva."}}, {"n": 11, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, «ubicación espacio-temporal» significa:", "opciones": {"A": "conocer la historia del atletismo.", "B": "elegir el carril que más te guste.", "C": "saber dónde estás y cuándo hacer cada acción durante la prueba.", "D": "calcular la distancia total de la pista."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "En la posición de «¡Listos!», el atleta debe:", "opciones": {"A": "empezar a correr suavemente.", "B": "ponerse de pie completamente.", "C": "mover los brazos para calentar.", "D": "elevar la cadera y quedarse inmóvil."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "Durante una carrera de 100 metros, si un corredor se pasa al carril de al lado, lo más probable es que:", "opciones": {"A": "deba repetir la salida.", "B": "incumpla la regla de permanecer en su carril.", "C": "gane ventaja legalmente.", "D": "reciba más tiempo para terminar."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Según el segundo texto, ¿qué es tan importante como la fuerza de las piernas?", "opciones": {"A": "La ubicación en el espacio y en el tiempo durante la carrera.", "B": "El tipo de tacos de salida.", "C": "La altura del atleta.", "D": "El color del uniforme."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuáles son las cuatro fases del salto largo?", "opciones": {"A": "Calentamiento, carrera, salto y descanso.", "B": "Salida, aceleración, llegada y medición.", "C": "Batida, carrera, caída y vuelo.", "D": "Carrera de impulso, batida, vuelo y caída."}}, {"n": 16, "seccion": 3, "competencia": "Literal", "enunciado": "La batida en el salto largo se realiza:", "opciones": {"A": "después de la línea de batida.", "B": "con las manos apoyadas en la tabla.", "C": "con los dos pies juntos.", "D": "con un solo pie, sin pasar la línea."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el atleta flexiona las rodillas al caer?", "opciones": {"A": "Para ganar velocidad en la carrera de impulso.", "B": "Porque el reglamento lo exige para que el salto sea válido.", "C": "Para amortiguar el impacto y no perder el equilibrio.", "D": "Para medir mejor su salto."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un atleta salta 4 metros pero al caer apoya una mano detrás de los pies. ¿Qué pasa con su marca?", "opciones": {"A": "Se mide hasta los pies y no cuenta la mano.", "B": "Se mide hasta la huella de la mano, porque es la más cercana a la línea.", "C": "Se le suman los centímetros de la mano.", "D": "El salto queda anulado automáticamente."}}, {"n": 19, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, la palabra «nulo» significa que el salto:", "opciones": {"A": "no es válido.", "B": "fue realizado sin carrera.", "C": "fue el más largo.", "D": "debe medirse dos veces."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué tienen en común los tres textos?", "opciones": {"A": "Muestran que en el atletismo la técnica, el equilibrio y la ubicación son tan importantes como la fuerza.", "B": "Describen solo las pruebas de lanzamiento.", "C": "Explican la historia de los Juegos Olímpicos.", "D": "Afirman que el atletismo no necesita entrenamiento."}}]}, {"id": "2027-g7-p1-quiz", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Quiz — Futsal: origen y reglas básicas (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Un deporte nacido en Sudamérica", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El fútbol de salón o futsal nació en 1930 en Montevideo, Uruguay. El profesor Juan Carlos Ceriani adaptó el fútbol a canchas pequeñas y cerradas para que los jóvenes pudieran jugar en cualquier época del año. Hoy el futsal está reglamentado por la FIFA y se juega en todo el mundo; Colombia ha tenido selecciones destacadas en esta disciplina.<br><br>Cada equipo tiene cinco jugadores en la cancha, uno de ellos el portero. El partido dura dos tiempos de 20 minutos de juego cronometrado: el reloj se detiene cada vez que el balón sale o el árbitro para el juego. El balón es más pequeño y pesado que el del fútbol (tamaño 4) y rebota menos, lo que favorece jugarlo por el suelo y controlarlo con la planta del pie. Los cambios son ilimitados y «volantes»: un jugador puede salir y volver a entrar varias veces, siempre por la zona de sustitución. Cuando el balón sale por la banda, el juego se reanuda con un saque con el pie, no con las manos, y el jugador tiene cuatro segundos para hacerlo. Estas reglas hacen que el futsal sea rápido, técnico y con muchos toques de balón."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué país nació el futsal?", "opciones": {"A": "España.", "B": "Uruguay.", "C": "Brasil.", "D": "Colombia."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores tiene cada equipo en la cancha?", "opciones": {"A": "Cinco, incluido el portero.", "B": "Seis, incluido el portero.", "C": "Once, igual que en el fútbol.", "D": "Siete, sin contar el portero."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto dura cada tiempo de un partido de futsal?", "opciones": {"A": "20 minutos de juego cronometrado.", "B": "10 minutos cronometrados.", "C": "45 minutos corridos.", "D": "30 minutos con el reloj sin detener."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "Que el tiempo sea «cronometrado» significa que:", "opciones": {"A": "el reloj se detiene cada vez que el juego se para.", "B": "el árbitro decide cuánto dura el partido.", "C": "cada equipo controla su propio tiempo.", "D": "el reloj nunca se detiene."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el balón de futsal favorece el juego por el suelo?", "opciones": {"A": "Porque la cancha es de arena.", "B": "Porque es más liviano que el de fútbol.", "C": "Porque es más pequeño y pesado, y rebota menos.", "D": "Porque está prohibido elevar el balón."}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "Cuando el balón sale por la banda, el juego se reanuda:", "opciones": {"A": "con un tiro libre desde el centro.", "B": "con un saque con el pie.", "C": "con un bote neutral del árbitro.", "D": "con un saque con las manos."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene el jugador para hacer el saque de banda?", "opciones": {"A": "Seis segundos.", "B": "Cuatro segundos.", "C": "No hay límite de tiempo.", "D": "Diez segundos."}}, {"n": 8, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, los cambios «volantes» son aquellos en los que:", "opciones": {"A": "el cambio lo decide el árbitro.", "B": "el jugador que sale no puede regresar.", "C": "un jugador puede salir y volver a entrar varias veces.", "D": "solo se permiten tres cambios por partido."}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Durante un partido, tu equipo quiere hacer un cambio. ¿Qué debe respetar?", "opciones": {"A": "Que el jugador que entra sea el portero.", "B": "Que el partido esté en el segundo tiempo.", "C": "Que el árbitro detenga el reloj.", "D": "Que el cambio se haga por la zona de sustitución."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿por qué el futsal es un deporte rápido y técnico?", "opciones": {"A": "Porque los partidos son más largos.", "B": "Porque no tiene reglas oficiales.", "C": "Porque se juega con más jugadores que el fútbol.", "D": "Porque sus reglas favorecen muchos toques de balón y un juego continuo."}}], "modalidad": "Quiz"}, {"id": "2027-g7-p1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Futsal: fundamentos técnicos (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "La conducción y el control del balón", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "En el futsal el espacio es reducido y los rivales están cerca, por eso dominar el balón es fundamental. La conducción consiste en avanzar con el balón controlado. En la cancha pequeña se conduce mucho con la planta del pie, que permite frenar, arrastrar el balón hacia atrás o hacia los lados y cambiar de dirección rápidamente. También se usan el borde interno y el borde externo del pie. Durante la conducción, el jugador debe levantar la cabeza para observar a sus compañeros y a los rivales, y mantener el balón cerca del pie para protegerlo.<br><br>El control o recepción es la acción de dominar un balón que llega. Un buen control «amortigua» el balón: el pie retrocede un poco en el momento del contacto para quitarle velocidad, igual que cuando se atrapa un huevo con la mano. Si el pie queda rígido, el balón rebota lejos y se pierde la posesión. Antes de recibir, el jugador experto ya ha mirado el espacio libre, de modo que el primer toque deja el balón listo para la siguiente acción."}, {"id": 2, "titulo": "El pase y el remate", "instruccion": "(Responda las preguntas 8 a 13 con base en el siguiente texto.)", "cuerpo": "El pase es la acción técnica más usada en el futsal. El pase con el borde interno del pie es el más preciso, porque la superficie de contacto es amplia; se usa para distancias cortas y medias. El pie de apoyo se coloca al lado del balón, apuntando hacia el compañero, y el tobillo se mantiene firme. El pase con la planta y el pase con la punta del pie se usan para jugadas rápidas en espacios muy reducidos.<br><br>El remate es el golpe al balón con intención de hacer gol. En el futsal se remata mucho con la punta del pie (puntera), porque es un golpe rápido que casi no necesita impulso y sorprende al portero. El remate con el empeine es más potente, pero necesita más espacio y tiempo. Para rematar bien, el jugador mira la portería, ubica al portero y elige el lado contrario a su posición. La precisión es más importante que la fuerza: un remate suave y bien dirigido suele ser más efectivo que un golpe fuerte sin dirección."}, {"id": 3, "titulo": "Reglas que influyen en la técnica", "instruccion": "(Responda las preguntas 14 a 20 con base en el siguiente texto.)", "cuerpo": "El reglamento del futsal cambia la forma de jugar. Como el saque de banda se hace con el pie, los equipos ensayan jugadas preparadas a partir de él. El portero, cuando controla el balón en su propia mitad, tiene solo cuatro segundos para jugarlo, lo que lo obliga a pensar rápido y a tener buena técnica con los pies. Además, las faltas se acumulan: a partir de la sexta falta acumulada de un equipo en cada tiempo, el rival cobra un tiro libre directo sin barrera desde el segundo punto penal, ubicado a 10 metros de la portería. El primer punto penal está a 6 metros.<br><br>Por esta regla, los jugadores aprenden a defender sin cometer faltas: se colocan entre el rival y la portería, flexionan las piernas y esperan el momento adecuado para quitar el balón. En el futsal la barrida (lanzarse al suelo para quitar el balón) está muy restringida: si se hace de forma imprudente o temeraria contra un rival, se sanciona como falta."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué superficie del pie se usa mucho para conducir en el futsal?", "opciones": {"A": "La planta del pie.", "B": "Solo la punta del pie.", "C": "La rodilla.", "D": "El talón."}}, {"n": 2, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el jugador debe levantar la cabeza mientras conduce?", "opciones": {"A": "Para evitar mirar el balón.", "B": "Para observar a compañeros y rivales y decidir mejor.", "C": "Porque el reglamento lo exige.", "D": "Para correr más rápido."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «amortiguar» el balón significa:", "opciones": {"A": "patearlo con más fuerza.", "B": "levantarlo por encima de la cabeza.", "C": "dejarlo rebotar en la pared.", "D": "quitarle velocidad en el momento de recibirlo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "Si un jugador recibe el balón con el pie rígido, lo más probable es que:", "opciones": {"A": "el balón quede pegado al pie.", "B": "el balón rebote lejos y se pierda la posesión.", "C": "el árbitro sancione una falta.", "D": "haga un pase perfecto."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Vas a recibir un pase y un rival se acerca rápido. Según el texto, ¿qué deberías hacer antes de recibir?", "opciones": {"A": "Pedir al árbitro que detenga el juego.", "B": "Esperar quieto a que llegue el balón.", "C": "Cerrar los ojos para concentrarte.", "D": "Mirar el espacio libre para que el primer toque prepare la siguiente acción."}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "¿Por qué se compara el control del balón con atrapar un huevo?", "opciones": {"A": "Porque se debe hacer muy rápido.", "B": "Porque en ambos casos hay que ceder un poco para no rebotar o romper.", "C": "Porque el balón de futsal es frágil.", "D": "Porque se recibe con las manos."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del primer texto?", "opciones": {"A": "Dominar la conducción y el control es clave en un espacio reducido.", "B": "En el futsal no es importante controlar el balón.", "C": "Solo los porteros necesitan buena técnica.", "D": "El futsal se juega principalmente por el aire."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es el pase más preciso, según el texto?", "opciones": {"A": "El pase con el borde interno del pie.", "B": "El pase con la cabeza.", "C": "El pase con el talón.", "D": "El pase con el empeine."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Al hacer un pase con el borde interno, el pie de apoyo se coloca:", "opciones": {"A": "lejos del balón, a un metro.", "B": "encima del balón.", "C": "al lado del balón, apuntando hacia el compañero.", "D": "detrás del balón, apuntando hacia atrás."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el remate de puntera es frecuente en el futsal?", "opciones": {"A": "Porque es rápido, necesita poco impulso y sorprende al portero.", "B": "Porque es el único remate permitido.", "C": "Porque siempre va por arriba.", "D": "Porque es el remate más potente que existe."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Estás frente al arco y el portero se cubre el lado derecho. ¿Qué te recomienda el texto?", "opciones": {"A": "Rematar hacia el lado donde está el portero.", "B": "Patear lo más fuerte posible hacia el centro.", "C": "Rematar con precisión hacia el lado contrario a su posición.", "D": "Devolver el balón a tu portero."}}, {"n": 12, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el término «empeine» se refiere a:", "opciones": {"A": "la parte inferior del pie.", "B": "la punta de los dedos.", "C": "el borde externo del tobillo.", "D": "la parte superior del pie."}}, {"n": 13, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Según el segundo texto, ¿qué es más importante en el remate?", "opciones": {"A": "Rematar desde lejos.", "B": "Rematar siempre con el empeine.", "C": "La fuerza sin dirección.", "D": "La precisión."}}, {"n": 14, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene el portero para jugar el balón cuando lo controla en su propia mitad?", "opciones": {"A": "Diez segundos.", "B": "No tiene límite.", "C": "Seis segundos.", "D": "Cuatro segundos."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Desde qué distancia se cobra el tiro libre a partir de la sexta falta acumulada?", "opciones": {"A": "Desde el primer punto penal, a 6 metros.", "B": "Desde la mitad de la cancha.", "C": "Desde el segundo punto penal, a 10 metros.", "D": "Desde donde se cometió la falta, con barrera."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué la regla de las faltas acumuladas cambia la forma de defender?", "opciones": {"A": "Porque solo el portero puede defender.", "B": "Porque obliga a quitar el balón sin cometer faltas.", "C": "Porque elimina la defensa.", "D": "Porque permite hacer más barridas."}}, {"n": 17, "seccion": 3, "competencia": "Aplicación", "enunciado": "Tu equipo lleva cinco faltas acumuladas en el primer tiempo. ¿Qué actitud defensiva es la más conveniente?", "opciones": {"A": "Barrerse con fuerza en cada jugada.", "B": "Empujar al rival para que pierda el balón.", "C": "Ubicarse entre el rival y la portería y esperar el momento para quitar el balón.", "D": "Dejar de defender hasta el segundo tiempo."}}, {"n": 18, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, una barrida «temeraria» es una acción:", "opciones": {"A": "muy lenta y cuidadosa.", "B": "permitida por el reglamento.", "C": "realizada sin considerar el peligro para el rival.", "D": "que solo puede hacer el portero."}}, {"n": 19, "seccion": 3, "competencia": "Literal", "enunciado": "¿A qué distancia de la portería está el primer punto penal?", "opciones": {"A": "A 9 metros.", "B": "A 6 metros.", "C": "A 11 metros.", "D": "A 10 metros."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué relación hay entre los tres textos?", "opciones": {"A": "Las reglas del futsal y el espacio reducido exigen una técnica precisa con el balón.", "B": "El reglamento del futsal no influye en la forma de jugar.", "C": "Los tres textos tratan sobre la historia del futsal.", "D": "El futsal se gana con fuerza física más que con técnica."}}]}, {"id": "2027-g8-p1-quiz", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Quiz — Voleibol: origen y reglas básicas (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Del Mintonette al voleibol", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En 1895, William G. Morgan, profesor en Holyoke (Estados Unidos), creó un juego para personas que buscaban una actividad menos brusca que el baloncesto. Lo llamó Mintonette; poco después se le cambió el nombre por volleyball, porque el balón se golpeaba «al vuelo», sin dejarlo caer. Hoy lo reglamenta la Federación Internacional de Voleibol (FIVB).<br><br>Cada equipo tiene seis jugadores en la cancha, separados del rival por una red. En la categoría de mayores, la red mide 2,43 metros de altura para los hombres y 2,24 metros para las mujeres. Cada equipo puede tocar el balón máximo tres veces antes de pasarlo al otro lado (el toque de bloqueo no se cuenta) y un mismo jugador no puede tocarlo dos veces seguidas. Se juega con el sistema de punto por jugada (rally point): cada jugada termina con un punto para alguno de los dos equipos, sin importar quién sacó. Un set lo gana el primer equipo que llega a 25 puntos con una diferencia de al menos dos; el partido lo gana quien gana tres sets. Si hay un quinto set, se juega a 15 puntos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Quién creó el voleibol?", "opciones": {"A": "William G. Morgan.", "B": "Pierre de Coubertin.", "C": "James Naismith.", "D": "Juan Carlos Ceriani."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál fue el primer nombre del voleibol?", "opciones": {"A": "Netball.", "B": "Mintonette.", "C": "Basket-volley.", "D": "Volley."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "El nombre volleyball se relaciona con golpear el balón:", "opciones": {"A": "con los pies.", "B": "con una raqueta.", "C": "después de un bote.", "D": "«al vuelo», sin dejarlo caer."}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores tiene cada equipo en la cancha?", "opciones": {"A": "Once.", "B": "Seis.", "C": "Cinco.", "D": "Siete."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas veces puede tocar el balón un equipo antes de pasarlo, sin contar el bloqueo?", "opciones": {"A": "Dos.", "B": "Las que necesite.", "C": "Tres.", "D": "Cuatro."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe el saque y, sin que nadie más toque el balón, vuelve a golpearlo. ¿Qué ocurre?", "opciones": {"A": "Se repite el saque.", "B": "Es válido, porque fue el primer toque.", "C": "Es válido si el balón no tocó el suelo.", "D": "Es falta, porque un jugador no puede tocar el balón dos veces seguidas."}}, {"n": 7, "seccion": 1, "competencia": "Lexical", "enunciado": "En el sistema «rally point»:", "opciones": {"A": "se juega por tiempo y no por puntos.", "B": "solo puntúa el equipo que saca.", "C": "cada jugada termina con un punto para alguno de los equipos.", "D": "los puntos valen doble en el quinto set."}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "El marcador de un set va 25 a 24. ¿Qué pasa?", "opciones": {"A": "El set continúa hasta que un equipo saque dos puntos de diferencia.", "B": "El set termina empatado.", "C": "Se juega un set extra.", "D": "Gana el equipo que tiene 25."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "¿A cuántos puntos se juega el quinto set?", "opciones": {"A": "A 21 puntos.", "B": "A 15 puntos.", "C": "A 10 puntos.", "D": "A 25 puntos."}}, {"n": 10, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué Morgan diseñó un juego con red que separa a los equipos?", "opciones": {"A": "Para crear una actividad sin contacto, menos brusca que el baloncesto.", "B": "Para que el juego fuera más violento.", "C": "Porque no había balones disponibles.", "D": "Para que se jugara solo al aire libre."}}], "modalidad": "Quiz"}, {"id": "2027-g8-p1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Voleibol: coordinación, ritmo y reglamento (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Los golpes básicos: toque de dedos y antebrazos", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El voleibol se juega con golpes, porque el balón no se puede retener ni lanzar. El toque de dedos (o pase alto) se usa para balones que llegan por encima de la cabeza. El jugador se ubica debajo del balón, con las piernas semiflexionadas y un pie un poco adelante; las manos forman una especie de canasta frente a la frente, con los pulgares y los índices formando un triángulo. El balón se toca con las yemas de los dedos y el impulso nace de la extensión coordinada de piernas y brazos, no solo de las muñecas.<br><br>El golpe de antebrazos (o recepción) se usa para balones bajos y para recibir el saque. Los brazos se juntan y se extienden, formando una superficie plana con los antebrazos; las manos se unen sin entrelazar los dedos. El contacto se hace con los antebrazos, por encima de las muñecas, y el movimiento sale de las piernas: los brazos no se balancean por encima de los hombros. La clave de ambos golpes es llegar a tiempo debajo del balón: los desplazamientos cortos y rápidos y el ritmo de los pasos son tan importantes como la posición de las manos."}, {"id": 2, "titulo": "El saque y la rotación", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Cada jugada comienza con un saque desde detrás de la línea de fondo. Después del pitazo del árbitro, el jugador tiene ocho segundos para sacar. El saque de abajo, golpeando el balón con la mano a la altura de la cadera, es el más fácil de aprender; el saque de tenis, golpeando por encima del hombro, es más potente. Durante el saque, el jugador no puede pisar la línea de fondo.<br><br>El voleibol exige que todos los jugadores pasen por todas las posiciones. Cuando un equipo recupera el derecho a sacar, sus jugadores rotan una posición en el sentido de las agujas del reloj, y el jugador que llega a la posición 1 (atrás a la derecha) es quien saca. Si un equipo no está en el orden correcto en el momento del saque, comete una falta de rotación y el rival gana el punto. Esta regla obliga a todos los jugadores a aprender a recibir, pasar y atacar, y a coordinarse con sus compañeros en el espacio."}, {"id": 3, "titulo": "Faltas frecuentes y juego limpio", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "Algunas faltas se repiten mucho en el voleibol escolar. La retención ocurre cuando el balón queda detenido en las manos o es acompañado en lugar de golpeado. El doble contacto ocurre cuando un mismo jugador toca el balón dos veces seguidas (excepto en el bloqueo o en el primer toque del equipo, cuando el contacto es en una misma acción). También es falta tocar la red con cualquier parte del cuerpo mientras se juega el balón, y pasar al campo contrario por debajo de la red interfiriendo con el rival.<br><br>El voleibol tiene una fuerte tradición de juego limpio. Los jugadores levantan la mano para reconocer cuando tocaron la red o el balón antes de que salga, aunque el árbitro no lo haya visto. Después de cada punto, el equipo se reúne unos segundos para animarse, corregir y planear la siguiente jugada. Este ritmo de comunicación constante hace del voleibol un deporte de cooperación: ningún jugador puede ganar solo, porque nadie puede tocar el balón dos veces seguidas."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Para qué balones se usa el toque de dedos?", "opciones": {"A": "Para balones que tocan el suelo.", "B": "Solo para el saque.", "C": "Para balones que llegan a la altura de las rodillas.", "D": "Para balones que llegan por encima de la cabeza."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "En el toque de dedos, el balón se toca con:", "opciones": {"A": "los antebrazos.", "B": "las yemas de los dedos.", "C": "los puños cerrados.", "D": "las palmas de las manos."}}, {"n": 3, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, el impulso del toque de dedos viene principalmente de:", "opciones": {"A": "un movimiento fuerte de las muñecas.", "B": "la extensión coordinada de piernas y brazos.", "C": "un salto lo más alto posible.", "D": "el movimiento de la cabeza."}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "En el golpe de antebrazos, las manos deben:", "opciones": {"A": "unirse sin entrelazar los dedos.", "B": "quedar separadas.", "C": "entrelazar los dedos con fuerza.", "D": "formar un triángulo frente a la frente."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero recibe el saque balanceando los brazos por encima de los hombros y el balón sale disparado hacia atrás. ¿Qué le corregirías?", "opciones": {"A": "Que el movimiento salga de las piernas y los brazos no suban por encima de los hombros.", "B": "Que reciba con las yemas de los dedos.", "C": "Que se quede quieto y espere el balón.", "D": "Que golpee con los puños cerrados."}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «semiflexionadas» indica que las piernas están:", "opciones": {"A": "cruzadas.", "B": "completamente estiradas.", "C": "levantadas del suelo.", "D": "un poco dobladas."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el primer texto, ¿qué es tan importante como la posición de las manos?", "opciones": {"A": "Tener mucha fuerza en los brazos.", "B": "Ser el jugador más alto.", "C": "Llegar a tiempo debajo del balón con desplazamientos y ritmo adecuados.", "D": "Golpear siempre con la mano abierta."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene el jugador para sacar después del pitazo?", "opciones": {"A": "Ocho segundos.", "B": "Cinco segundos.", "C": "Diez segundos.", "D": "Tres segundos."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Desde dónde se realiza el saque?", "opciones": {"A": "Desde la mitad de la cancha.", "B": "Desde cualquier lugar de la cancha.", "C": "Desde detrás de la línea de fondo.", "D": "Junto a la red."}}, {"n": 10, "seccion": 2, "competencia": "Literal", "enunciado": "¿En qué sentido rota el equipo cuando recupera el saque?", "opciones": {"A": "En el sentido de las agujas del reloj.", "B": "De adelante hacia atrás sin orden.", "C": "En sentido contrario a las agujas del reloj.", "D": "Cada jugador elige su posición."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Cuál es la principal consecuencia educativa de la regla de rotación?", "opciones": {"A": "Los jugadores no necesitan comunicarse.", "B": "El mejor jugador saca siempre.", "C": "Todos los jugadores deben aprender a recibir, pasar y atacar.", "D": "Solo los jugadores altos atacan."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "En el momento del saque, dos jugadores de tu equipo están intercambiados de lugar. ¿Qué ocurre?", "opciones": {"A": "Se repite el saque sin sanción.", "B": "El árbitro les da una advertencia.", "C": "Es válido si nadie lo nota.", "D": "Es falta de rotación y el rival gana el punto."}}, {"n": 13, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el «saque de tenis» se caracteriza por:", "opciones": {"A": "usar una raqueta.", "B": "lanzar el balón con las dos manos.", "C": "golpear el balón por encima del hombro.", "D": "golpear el balón a la altura de la cadera."}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Quién saca después de una rotación?", "opciones": {"A": "El jugador que llega a la posición 1, atrás a la derecha.", "B": "El jugador que hizo el último punto.", "C": "El capitán del equipo.", "D": "El jugador más cercano a la red."}}, {"n": 15, "seccion": 3, "competencia": "Lexical", "enunciado": "En el tercer texto, la «retención» es:", "opciones": {"A": "tocar la red con la mano.", "B": "sacar fuera de la cancha.", "C": "dejar el balón detenido o acompañarlo en lugar de golpearlo.", "D": "rotar en el sentido incorrecto."}}, {"n": 16, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuándo es válido que un mismo jugador toque el balón dos veces seguidas?", "opciones": {"A": "En el tercer toque del equipo.", "B": "Siempre que el balón no toque el suelo.", "C": "Cuando el equipo va perdiendo.", "D": "En el bloqueo, o en el primer toque del equipo cuando ocurre en una misma acción."}}, {"n": 17, "seccion": 3, "competencia": "Aplicación", "enunciado": "Al rematar cerca de la red, un jugador la roza con la camiseta mientras juega el balón. ¿Qué indica el texto?", "opciones": {"A": "Es falta únicamente en el quinto set.", "B": "Es falta tocar la red mientras se juega el balón.", "C": "Es válido porque fue con la camiseta.", "D": "Solo es falta si la red se cae."}}, {"n": 18, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el texto dice que en el voleibol «ningún jugador puede ganar solo»?", "opciones": {"A": "Porque los equipos tienen más de diez jugadores.", "B": "Porque nadie puede tocar el balón dos veces seguidas y se necesitan los compañeros.", "C": "Porque el árbitro decide quién gana.", "D": "Porque el balón es muy pesado."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Un jugador levanta la mano para reconocer que tocó la red, aunque el árbitro no lo vio. Esta actitud demuestra:", "opciones": {"A": "miedo a perder.", "B": "desconocimiento del reglamento.", "C": "falta de concentración.", "D": "juego limpio y honestidad."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué idea une los tres textos?", "opciones": {"A": "El voleibol no tiene reglas sobre el saque.", "B": "El voleibol exige coordinación, ritmo y respeto de las reglas en equipo.", "C": "El voleibol se basa en la fuerza individual.", "D": "Solo importa la técnica de los golpes."}}]}, {"id": "2027-g9-p1-quiz", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Quiz — Baloncesto: reglas de tiempo y espacio (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Un juego de reglas y segundos", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El baloncesto fue creado en 1891 por James Naismith en Springfield (Estados Unidos). Hoy la FIBA (Federación Internacional de Baloncesto) establece que cada equipo tiene cinco jugadores en la cancha y que el partido se divide en cuatro cuartos de 10 minutos.<br><br>Varias reglas se refieren al tiempo. Un equipo tiene 24 segundos para lanzar al aro cada vez que tiene la posesión; si no lo hace, pierde el balón. Tiene 8 segundos para pasar el balón de su campo defensivo al campo de ataque. Un atacante no puede permanecer más de 3 segundos seguidos dentro de la zona restringida (la «pintura») del rival. Y un jugador que está siendo marcado de cerca tiene 5 segundos para pasar, lanzar o botar el balón.<br><br>Otras reglas se refieren al movimiento. Es violación de pasos (o caminar) avanzar con el balón en las manos sin botarlo, y es violación de dobles botar, agarrar el balón y volver a botarlo. En cuanto a las faltas, un jugador que comete cinco faltas personales debe salir del partido. Un lanzamiento convertido desde fuera de la línea de 6,75 metros vale tres puntos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos segundos tiene un equipo para lanzar al aro en cada posesión?", "opciones": {"A": "30 segundos.", "B": "12 segundos.", "C": "24 segundos.", "D": "8 segundos."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene un equipo para pasar el balón a su campo de ataque?", "opciones": {"A": "3 segundos.", "B": "8 segundos.", "C": "24 segundos.", "D": "5 segundos."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la «pintura» es:", "opciones": {"A": "la banca de los suplentes.", "B": "la línea de tres puntos.", "C": "el círculo central.", "D": "la zona restringida cerca del aro."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un pívot atacante se queda 4 segundos seguidos en la pintura del rival. ¿Qué ocurre?", "opciones": {"A": "Comete violación de 3 segundos y pierde el balón.", "B": "Recibe una falta técnica.", "C": "El juego continúa sin sanción.", "D": "Es válido si no tiene el balón."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos cuartos tiene un partido según la FIBA?", "opciones": {"A": "Cuatro cuartos de 10 minutos.", "B": "Cuatro cuartos de 12 minutos.", "C": "Dos tiempos de 20 minutos.", "D": "Tres periodos de 15 minutos."}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "La violación de «dobles» consiste en:", "opciones": {"A": "pasar el balón con dos manos.", "B": "botar, agarrar el balón y volver a botarlo.", "C": "lanzar dos veces seguidas al aro.", "D": "cometer dos faltas personales."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe el balón, da tres pasos sin botarlo y lanza. ¿Qué cometió?", "opciones": {"A": "Violación de pasos (caminar).", "B": "Violación de dobles.", "C": "Falta personal.", "D": "Ninguna, porque lanzó al aro."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué le pasa a un jugador que comete cinco faltas personales?", "opciones": {"A": "Su equipo pierde 5 puntos.", "B": "Recibe un tiro libre en contra.", "C": "Debe salir del partido.", "D": "Debe sentarse un cuarto completo."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la regla de los 24 segundos?", "opciones": {"A": "Para que los partidos duren más.", "B": "Para dar descanso a los jugadores.", "C": "Para favorecer al equipo que defiende siempre.", "D": "Para que el juego sea dinámico y los equipos no retengan el balón sin atacar."}}, {"n": 10, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos puntos vale un lanzamiento convertido desde fuera de la línea de 6,75 metros?", "opciones": {"A": "Dos puntos.", "B": "Tres puntos.", "C": "Un punto.", "D": "Cuatro puntos."}}], "modalidad": "Quiz"}, {"id": "2027-g9-p1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Baloncesto: estrategia y táctica (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Principios del ataque", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "En el baloncesto, la técnica individual no basta: el equipo necesita una estrategia, es decir, un plan para conseguir ventaja sobre el rival. En el ataque existen principios básicos. El primero es ocupar bien los espacios: los jugadores se distribuyen por la cancha para que la defensa no pueda cubrirlos a todos y queden líneas de pase abiertas. El segundo es el «pasar y cortar»: el jugador que entrega el balón no se queda quieto, sino que se desplaza rápidamente hacia el aro o hacia un espacio libre para recibir de nuevo.<br><br>El tercer principio es buscar la superioridad numérica, por ejemplo un dos contra uno (2x1). Cuando dos atacantes enfrentan a un solo defensor, el atacante con balón debe atraer al defensor y pasar en el momento justo a su compañero libre. Finalmente, se busca el mejor lanzamiento posible: no el primero que aparece, sino el que tiene más probabilidad de entrar, normalmente cerca del aro o con el lanzador libre de marca. Un equipo que pasa bien el balón obliga a la defensa a moverse más y comete menos pérdidas."}, {"id": 2, "titulo": "Sistemas defensivos", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Las defensas se organizan principalmente de dos maneras. En la defensa individual, cada defensor se responsabiliza de un atacante y lo sigue por toda la cancha; exige buena condición física y concentración, porque cada jugador debe evitar que su rival reciba o avance con facilidad. En la defensa en zona, cada defensor protege un espacio de la cancha. La más conocida es la zona 2-3: dos jugadores adelante, cerca de la línea de tiros libres, y tres atrás, cerca del aro. La zona protege bien el área cercana al aro, pero deja más libres los lanzamientos desde lejos.<br><br>En ambos sistemas existe la «ayuda»: cuando un compañero es superado por su atacante, el defensor más cercano se desplaza para cerrar el camino al aro, y luego el equipo recupera sus posiciones. La comunicación es fundamental: los defensores se avisan con palabras cortas («¡cambio!», «¡ayuda!», «¡bloqueo!»). El rebote defensivo cierra la jugada: si el equipo no recupera el balón después de un lanzamiento fallado del rival, la buena defensa no sirve de nada."}, {"id": 3, "titulo": "El contraataque y la lectura del juego", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "El contraataque es un ataque rápido que se realiza inmediatamente después de recuperar el balón, antes de que el rival organice su defensa. Comienza con el rebote o el robo, sigue con un pase de salida rápido hacia un jugador que corre por la banda y termina con una entrada al aro, muchas veces en situación de superioridad numérica. Para que funcione, los jugadores deben ocupar tres carriles imaginarios: uno central, para el que conduce el balón, y dos laterales, para los que corren por las bandas.<br><br>Leer el juego significa observar lo que hace el rival y tomar la mejor decisión en cada momento. Si la defensa es en zona y deja libres los lanzamientos lejanos, conviene mover rápido el balón y lanzar de media o larga distancia. Si la defensa es individual y un rival es más lento, conviene atacarlo en el uno contra uno. Un buen equipo no repite siempre la misma jugada: se adapta a lo que el adversario le permite y respeta las decisiones del árbitro aunque no las comparta."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «estrategia» significa:", "opciones": {"A": "la habilidad de botar con las dos manos.", "B": "un plan para conseguir ventaja sobre el rival.", "C": "la fuerza física de los jugadores.", "D": "el reglamento oficial del baloncesto."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué consiste el «pasar y cortar»?", "opciones": {"A": "Pasar solo hacia atrás.", "B": "Cortar el pase del rival.", "C": "Después de pasar, el jugador se desplaza hacia el aro o un espacio libre para recibir de nuevo.", "D": "Pasar el balón y quedarse quieto."}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un 2x1, tú llevas el balón y el defensor no se acerca a ti. ¿Qué es lo más conveniente?", "opciones": {"A": "Lanzar desde la mitad de la cancha.", "B": "Pasar de inmediato aunque tu compañero esté marcado.", "C": "Avanzar hacia el aro, porque el defensor no te está marcando.", "D": "Detenerte y esperar a los demás."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué ocupar bien los espacios favorece al ataque?", "opciones": {"A": "Porque la defensa no puede cubrir a todos y quedan líneas de pase abiertas.", "B": "Porque el reglamento lo exige.", "C": "Porque así los atacantes descansan.", "D": "Porque reduce el número de pases."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál es el mejor lanzamiento?", "opciones": {"A": "El que tiene más probabilidad de entrar.", "B": "El más lejano posible.", "C": "El que lanza el jugador más alto.", "D": "El primero que aparece."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Qué consecuencia tiene pasar bien el balón?", "opciones": {"A": "El partido se vuelve más lento.", "B": "El equipo lanza menos al aro.", "C": "La defensa se mueve más y el equipo pierde menos balones.", "D": "Los defensores descansan más."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea central del primer texto?", "opciones": {"A": "Los pases no influyen en el resultado.", "B": "El baloncesto se gana con el jugador más alto.", "C": "Solo importa lanzar desde lejos.", "D": "El ataque necesita principios colectivos, no solo técnica individual."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En la defensa individual:", "opciones": {"A": "cada defensor se responsabiliza de un atacante.", "B": "solo defienden tres jugadores.", "C": "cada defensor protege una zona de la cancha.", "D": "los defensores no se mueven."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cómo se ubican los jugadores en la zona 2-3?", "opciones": {"A": "Todos debajo del aro.", "B": "Dos adelante, cerca de la línea de tiros libres, y tres atrás, cerca del aro.", "C": "Tres adelante y dos atrás.", "D": "Uno adelante y cuatro atrás."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Cuál es la debilidad de la defensa en zona, según el texto?", "opciones": {"A": "No permite la ayuda defensiva.", "B": "Deja más libres los lanzamientos desde lejos.", "C": "Exige más condición física que la individual.", "D": "No protege el área cerca del aro."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu compañero es superado por su atacante, que va hacia el aro. ¿Qué debes hacer si eres el defensor más cercano?", "opciones": {"A": "Cometer una falta intencional siempre.", "B": "Pedir tiempo muerto.", "C": "Quedarte con tu atacante sin moverte.", "D": "Desplazarte para cerrar el camino al aro (ayuda) y luego recuperar posición."}}, {"n": 12, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el «rebote defensivo» es:", "opciones": {"A": "una falta del atacante.", "B": "un pase que rebota en el suelo.", "C": "recuperar el balón después de un lanzamiento fallado del rival.", "D": "un tipo de defensa en zona."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la comunicación es fundamental en la defensa?", "opciones": {"A": "Porque está prohibido hacer señas.", "B": "Porque el árbitro necesita escucharlos.", "C": "Porque los defensores deben coordinar ayudas, cambios y bloqueos.", "D": "Porque así se distrae al rival."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Según el segundo texto, ¿por qué una buena defensa «no sirve de nada» sin rebote?", "opciones": {"A": "Porque el rebote vale puntos extra.", "B": "Porque el rival tendría otra oportunidad de anotar.", "C": "Porque la defensa debe cambiar de sistema.", "D": "Porque el árbitro anula la jugada."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuándo se realiza el contraataque?", "opciones": {"A": "Al inicio de cada cuarto.", "B": "Solo en los últimos minutos.", "C": "Después de un tiempo muerto.", "D": "Inmediatamente después de recuperar el balón, antes de que el rival se organice."}}, {"n": 16, "seccion": 3, "competencia": "Literal", "enunciado": "En el contraataque, el carril central lo ocupa:", "opciones": {"A": "el entrenador.", "B": "el jugador más alto.", "C": "el defensor rival.", "D": "el jugador que conduce el balón."}}, {"n": 17, "seccion": 3, "competencia": "Aplicación", "enunciado": "El rival defiende en zona y deja libres los lanzamientos lejanos. ¿Qué te recomienda el texto?", "opciones": {"A": "Mover rápido el balón y lanzar de media o larga distancia.", "B": "Usar siempre el contraataque.", "C": "Dejar de lanzar y solo pasar.", "D": "Atacar siempre por el centro de la zona."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Notas que tu marcador es más lento que tú y defienden en individual. ¿Qué decisión es la más adecuada?", "opciones": {"A": "Atacarlo en el uno contra uno.", "B": "Esperar a que se acaben los 24 segundos.", "C": "Lanzar desde la mitad de la cancha.", "D": "Pasar el balón siempre al pívot."}}, {"n": 19, "seccion": 3, "competencia": "Lexical", "enunciado": "«Leer el juego» significa:", "opciones": {"A": "conocer de memoria el reglamento.", "B": "observar lo que hace el rival y tomar la mejor decisión.", "C": "repetir siempre la misma jugada.", "D": "mirar el marcador constantemente."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué conclusión une los tres textos?", "opciones": {"A": "Las jugadas deben ser siempre las mismas.", "B": "La defensa no es importante para ganar.", "C": "El baloncesto depende solo de la estatura.", "D": "En el baloncesto gana quien coordina al equipo y toma buenas decisiones según el rival."}}]}, {"id": "2027-g10-p1-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Quiz — Fútbol: Reglas de Juego básicas (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Las Reglas de Juego", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las Reglas de Juego del fútbol las establece la IFAB (International Football Association Board) y las aplica la FIFA en todo el mundo. Cada equipo tiene once jugadores, uno de ellos el guardameta, y un partido no puede comenzar si alguno tiene menos de siete. El partido dura dos tiempos de 45 minutos, más el tiempo que el árbitro añada por pérdidas de tiempo.<br><br>Se concede un tiro penal cuando un jugador comete una falta que se sanciona con tiro libre directo dentro de su propia área penal; el penal se cobra desde 11 metros. Las faltas más leves se sancionan con tiro libre indirecto, en el que el gol solo es válido si el balón toca a otro jugador antes de entrar. La tarjeta amarilla es una amonestación; la roja es una expulsión, y el jugador expulsado no puede ser reemplazado.<br><br>Un jugador está en posición de fuera de juego si, en el momento en que un compañero juega el balón, está en la mitad del campo rival y más cerca de la línea de meta que el balón y que el penúltimo adversario. Estar en esa posición no es una infracción por sí mismo: solo se sanciona si el jugador participa en la jugada. Además, no hay fuera de juego si el jugador recibe directamente de un saque de meta, de banda o de esquina."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué organismo establece las Reglas de Juego del fútbol?", "opciones": {"A": "La IFAB.", "B": "El Comité Olímpico.", "C": "La FIVB.", "D": "La FIBA."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es el número mínimo de jugadores para iniciar un partido?", "opciones": {"A": "Siete por equipo.", "B": "Once por equipo.", "C": "Cinco por equipo.", "D": "Nueve por equipo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Desde qué distancia se cobra el tiro penal?", "opciones": {"A": "6 metros.", "B": "11 metros.", "C": "16 metros.", "D": "9 metros."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En un tiro libre «indirecto», el gol es válido solo si:", "opciones": {"A": "se patea con el pie izquierdo.", "B": "se cobra desde fuera del área.", "C": "el balón toca a otro jugador antes de entrar.", "D": "el portero no se mueve."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe tarjeta roja en el minuto 30. ¿Qué ocurre con su equipo?", "opciones": {"A": "Pierde automáticamente el partido.", "B": "Sigue jugando con un jugador menos, porque el expulsado no puede ser reemplazado.", "C": "Puede reemplazarlo con un suplente.", "D": "Debe cobrar un penal en contra."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el árbitro añade tiempo al final de cada tiempo?", "opciones": {"A": "Para que los jugadores descansen.", "B": "Porque el reglamento exige 50 minutos.", "C": "Para compensar el tiempo perdido durante el partido.", "D": "Para que el equipo que pierde pueda empatar."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "Para estar en posición de fuera de juego, el jugador debe estar:", "opciones": {"A": "detrás del balón.", "B": "en la mitad rival, más cerca de la línea de meta que el balón y que el penúltimo adversario.", "C": "en su propia mitad del campo.", "D": "a la misma altura del penúltimo adversario."}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un delantero recibe directamente de un saque de banda estando detrás de todos los defensores. ¿Hay fuera de juego?", "opciones": {"A": "Sí, siempre que esté detrás de los defensores.", "B": "Solo si el árbitro lo considera peligroso.", "C": "Sí, si el balón llega por el aire.", "D": "No, porque desde un saque de banda no hay fuera de juego."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un jugador en posición de fuera de juego que no participa en la jugada:", "opciones": {"A": "no comete infracción.", "B": "recibe tarjeta amarilla.", "C": "debe salir del campo.", "D": "siempre es sancionado."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Para qué sirven, en general, las Reglas de Juego?", "opciones": {"A": "Para que los árbitros decidan el resultado.", "B": "Para que el fútbol sea más lento.", "C": "Para que gane el equipo con más jugadores.", "D": "Para que el partido sea justo, seguro y igual para todos."}}], "modalidad": "Quiz"}, {"id": "2027-g10-p1", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Fútbol: reglamento, táctica y ritmo de juego (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Faltas, sanciones y juego limpio", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El árbitro sanciona con tiro libre directo las acciones que un jugador comete contra un adversario de manera imprudente, temeraria o con uso de fuerza excesiva: cargar, empujar, golpear, poner una zancadilla o sujetar a un rival, entre otras. También es tiro libre directo tocar el balón deliberadamente con la mano o el brazo, excepto el guardameta dentro de su área. Una acción imprudente se castiga solo con la falta; una temeraria, con tarjeta amarilla; y una con fuerza excesiva, con tarjeta roja.<br><br>El árbitro puede aplicar la «ventaja»: si después de una falta el equipo que la sufrió sigue teniendo una buena opción de ataque, deja continuar el juego en lugar de detenerlo, y puede amonestar al infractor cuando el balón quede fuera de juego. El reglamento busca proteger la integridad física de los jugadores y premiar a quien juega con limpieza. Por eso, actitudes como devolver el balón al rival cuando se detuvo el juego por una lesión no están escritas como obligación, pero hacen parte del espíritu del fútbol."}, {"id": 2, "titulo": "Sistemas tácticos y transiciones", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Un sistema táctico es la forma en que un equipo distribuye a sus jugadores en el campo. Se nombra con números que van desde la defensa hasta el ataque, sin contar al portero, aunque a veces se escribe el 1 inicial para incluirlo. En el 1-4-4-2 hay cuatro defensas, cuatro mediocampistas y dos delanteros; es un sistema equilibrado. En el 1-4-3-3 hay tres mediocampistas y tres delanteros, lo que favorece el juego por las bandas y la presión en campo rival.<br><br>El fútbol moderno se piensa en cuatro momentos: ataque organizado, defensa organizada y dos transiciones. La transición ataque-defensa ocurre cuando el equipo pierde el balón: los jugadores más cercanos presionan de inmediato para recuperarlo o retrasar al rival, mientras el resto vuelve a su posición. La transición defensa-ataque ocurre al recuperarlo: se busca salir rápido hacia el arco rival antes de que la defensa contraria se organice. Los equipos que dominan las transiciones suelen anotar más goles, porque aprovechan los momentos en que el rival está desordenado."}, {"id": 3, "titulo": "El ritmo del juego y la expresión del jugador", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "Un partido de fútbol tiene ritmo, como una pieza musical. Hay momentos de pausa, en los que el equipo se pasa el balón con calma para ordenarse, y momentos de aceleración, en los que un pase vertical, un cambio de frente o un regate rompen la defensa. Los jugadores inteligentes saben «cambiar el ritmo»: alternan pases cortos y largos, lentos y rápidos, para que el rival no adivine la siguiente acción. El cambio de ritmo también es individual: un delantero que conduce despacio y de repente acelera puede superar a un defensor más rápido que él.<br><br>El fútbol también es expresión corporal y cultural. Las celebraciones, los cantos de la hinchada y los estilos de juego de cada región muestran identidades diferentes. En Colombia, por ejemplo, se suele destacar el juego técnico y de toque. Valorar esas expresiones implica respetar al rival, a los árbitros y a las hinchadas contrarias: la diversidad hace más rica la cultura del fútbol, y la violencia en los estadios la destruye."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál de estas acciones se sanciona con tiro libre directo?", "opciones": {"A": "Estar en posición de fuera de juego sin participar.", "B": "Poner una zancadilla a un adversario de manera imprudente.", "C": "Celebrar un gol con el público.", "D": "Pedir el balón en voz alta."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Una acción temeraria contra un rival se sanciona con:", "opciones": {"A": "saque de banda.", "B": "tarjeta roja siempre.", "C": "tiro libre directo y tarjeta amarilla.", "D": "solo tiro libre indirecto."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, aplicar la «ventaja» significa:", "opciones": {"A": "dejar seguir el juego si el equipo que sufrió la falta tiene una buena opción de ataque.", "B": "permitir que un equipo tenga un jugador más.", "C": "dar un penal al equipo que va perdiendo.", "D": "añadir tiempo al final del partido."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un defensor golpea a un rival con fuerza excesiva en una disputa. ¿Qué debe hacer el árbitro?", "opciones": {"A": "Sancionar tiro libre indirecto.", "B": "Sancionar tiro libre directo y mostrar tarjeta roja.", "C": "Dejar seguir el juego sin sanción.", "D": "Mostrar solo tarjeta amarilla."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Cuál es el propósito principal del reglamento sobre faltas?", "opciones": {"A": "Proteger la integridad física de los jugadores y premiar el juego limpio.", "B": "Aumentar el número de tarjetas.", "C": "Hacer que los partidos tengan menos goles.", "D": "Favorecer a los equipos locales."}}, {"n": 6, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Devolver el balón al rival después de detener el juego por una lesión es un ejemplo de:", "opciones": {"A": "una regla obligatoria de la IFAB.", "B": "una estrategia para ganar tiempo.", "C": "juego limpio, aunque no sea una obligación del reglamento.", "D": "una falta que se sanciona con tarjeta."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué caso un jugador puede tocar el balón con la mano sin cometer falta?", "opciones": {"A": "En cualquier saque de esquina.", "B": "Cuando es el capitán.", "C": "Cuando es el guardameta dentro de su propia área.", "D": "Cuando el balón viene muy rápido."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En el sistema 1-4-4-2, ¿cuántos delanteros hay?", "opciones": {"A": "Dos.", "B": "Uno.", "C": "Tres.", "D": "Cuatro."}}, {"n": 9, "seccion": 2, "competencia": "Lexical", "enunciado": "Un «sistema táctico» es:", "opciones": {"A": "el uniforme de cada equipo.", "B": "el reglamento oficial del fútbol.", "C": "la forma en que un equipo distribuye a sus jugadores en el campo.", "D": "el entrenamiento físico del equipo."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el 1-4-3-3 favorece el juego por las bandas?", "opciones": {"A": "Porque tiene cinco defensas.", "B": "Porque el portero juega adelantado.", "C": "Porque no tiene mediocampistas.", "D": "Porque tiene tres delanteros, que pueden abrirse hacia los costados."}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "La transición ataque-defensa ocurre cuando el equipo:", "opciones": {"A": "recupera el balón.", "B": "cobra un tiro libre.", "C": "hace un cambio de jugador.", "D": "pierde el balón."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo acaba de recuperar el balón y el rival tiene a varios jugadores adelantados. ¿Qué es lo más conveniente según el texto?", "opciones": {"A": "Sacar el balón por la banda.", "B": "Pasar el balón hacia atrás y esperar.", "C": "Detener el juego para hacer un cambio.", "D": "Salir rápido hacia el arco rival antes de que se organice."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué los equipos que dominan las transiciones suelen anotar más?", "opciones": {"A": "Porque el árbitro los favorece.", "B": "Porque aprovechan los momentos en que el rival está desordenado.", "C": "Porque juegan más minutos.", "D": "Porque tienen más jugadores en el campo."}}, {"n": 14, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo pierde el balón en campo rival. ¿Qué deben hacer los jugadores más cercanos?", "opciones": {"A": "Detenerse y reclamar al árbitro.", "B": "Esperar a que el rival se equivoque.", "C": "Correr todos hacia su propia área.", "D": "Presionar de inmediato para recuperarlo o retrasar al rival."}}, {"n": 15, "seccion": 3, "competencia": "Lexical", "enunciado": "En el tercer texto, «cambiar el ritmo» significa:", "opciones": {"A": "cambiar la música del estadio.", "B": "cambiar de sistema táctico en cada jugada.", "C": "jugar siempre a la máxima velocidad.", "D": "alternar acciones lentas y rápidas para sorprender al rival."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Cómo puede un delantero superar a un defensor más rápido que él?", "opciones": {"A": "Esperando a que el defensor se canse.", "B": "Conduciendo despacio y acelerando de repente.", "C": "Pasando siempre hacia atrás.", "D": "Corriendo siempre a la misma velocidad."}}, {"n": 17, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, ¿qué ejemplos muestran el fútbol como expresión cultural?", "opciones": {"A": "Las medidas del campo y del balón.", "B": "Las celebraciones, los cantos de la hinchada y los estilos de juego regionales.", "C": "Las tarjetas amarillas y rojas.", "D": "Los sistemas 1-4-4-2 y 1-4-3-3."}}, {"n": 18, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué postura defiende el autor sobre la diversidad en el fútbol?", "opciones": {"A": "La diversidad enriquece la cultura del fútbol y la violencia la destruye.", "B": "Todas las hinchadas deberían animar igual.", "C": "Solo el estilo de toque es válido.", "D": "Las celebraciones deberían prohibirse."}}, {"n": 19, "seccion": 3, "competencia": "Aplicación", "enunciado": "En un partido escolar, un compañero se burla de la forma de celebrar del equipo rival. Según el texto, ¿qué actitud sería la adecuada?", "opciones": {"A": "Respetar la expresión del rival y animar a tu compañero a hacer lo mismo.", "B": "Burlarse también para defender al equipo.", "C": "Pedir al árbitro que expulse al rival.", "D": "Ignorar el partido y retirarse."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué idea integra los tres textos?", "opciones": {"A": "El fútbol depende solo de la técnica individual.", "B": "El reglamento es lo único importante.", "C": "Jugar bien al fútbol combina respetar las reglas, organizarse tácticamente y expresarse con respeto.", "D": "La táctica no tiene relación con el ritmo del juego."}}]}, {"id": "2027-g11-p1-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Quiz — Actividad física y salud (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "¿Cuánta actividad física necesitamos?", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La Organización Mundial de la Salud (OMS) recomienda que los niños y adolescentes de 5 a 17 años realicen, en promedio, al menos 60 minutos diarios de actividad física de intensidad moderada a vigorosa, principalmente aeróbica. Además, al menos tres días a la semana deberían incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. Para los adultos, la recomendación es de 150 a 300 minutos semanales de actividad moderada, o de 75 a 150 minutos de actividad vigorosa, más ejercicios de fuerza dos o más días por semana.<br><br>La intensidad moderada es aquella en la que la respiración y el pulso se aceleran, pero todavía se puede conversar; caminar a paso rápido o montar en bicicleta suave son ejemplos. En la intensidad vigorosa, como correr o jugar un partido, la respiración es tan agitada que cuesta hablar. La OMS también recomienda reducir el tiempo sedentario, por ejemplo el que se pasa frente a pantallas. La actividad física regular mejora la salud del corazón y los pulmones, fortalece huesos y músculos, ayuda a controlar el peso y favorece el bienestar mental y el rendimiento escolar."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánta actividad física diaria recomienda la OMS para adolescentes de 5 a 17 años?", "opciones": {"A": "Dos horas diarias de intensidad vigorosa.", "B": "Al menos 60 minutos en promedio, de intensidad moderada a vigorosa.", "C": "Una hora a la semana.", "D": "Al menos 20 minutos de intensidad suave."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos días a la semana deberían incluir actividades de fortalecimiento muscular y óseo los adolescentes?", "opciones": {"A": "Al menos tres.", "B": "Ninguno, solo actividad aeróbica.", "C": "Los siete días obligatoriamente.", "D": "Al menos uno."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "Según el texto, en una actividad de intensidad «moderada»:", "opciones": {"A": "es imposible hablar.", "B": "no se acelera el pulso.", "C": "solo se mueven los brazos.", "D": "la respiración se acelera, pero todavía se puede conversar."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál de estas actividades es vigorosa?", "opciones": {"A": "Correr o jugar un partido de fútbol.", "B": "Estar sentado leyendo.", "C": "Caminar despacio por el parque.", "D": "Estirarse suavemente."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es la recomendación semanal de actividad moderada para adultos?", "opciones": {"A": "No hay recomendación para adultos.", "B": "De 150 a 300 minutos.", "C": "De 30 a 60 minutos.", "D": "De 500 a 600 minutos."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la OMS recomienda reducir el tiempo frente a pantallas?", "opciones": {"A": "Porque es una regla del colegio.", "B": "Porque es tiempo sedentario que afecta la salud.", "C": "Porque así se estudia más.", "D": "Porque las pantallas impiden dormir siempre."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante camina 20 minutos al colegio y 20 de regreso, y juega 30 minutos en el descanso. ¿Cumple la recomendación diaria?", "opciones": {"A": "No, porque debe hacerlo de una sola vez.", "B": "Sí, pero solo si lo hace los fines de semana.", "C": "Sí, suma 70 minutos si la intensidad es al menos moderada.", "D": "No, porque caminar nunca cuenta."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál es un beneficio de la actividad física regular?", "opciones": {"A": "Elimina la necesidad de dormir.", "B": "Reemplaza una alimentación balanceada.", "C": "Solo mejora la apariencia física.", "D": "Favorece el bienestar mental y el rendimiento escolar."}}, {"n": 9, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «sedentario» se refiere a:", "opciones": {"A": "hacer ejercicio sentado.", "B": "vivir en una zona rural.", "C": "pasar mucho tiempo sentado o con muy poco movimiento.", "D": "entrenar de forma vigorosa."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la mejor conclusión del texto?", "opciones": {"A": "Moverse con regularidad y a la intensidad adecuada es una necesidad para la salud.", "B": "Basta con hacer ejercicio un día al mes.", "C": "Solo los deportistas necesitan actividad física.", "D": "La actividad física es útil únicamente para bajar de peso."}}], "modalidad": "Quiz"}, {"id": "2027-g11-p1", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Atletismo y plan personal de entrenamiento (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Los principios del entrenamiento", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Entrenar no es hacer ejercicio sin orden: es aplicar principios que permiten mejorar sin lesionarse. El principio de sobrecarga progresiva indica que el cuerpo solo mejora si recibe estímulos un poco mayores a los que está acostumbrado; por eso la carga (tiempo, distancia, velocidad o peso) se aumenta de forma gradual, no de golpe. El principio de especificidad dice que el cuerpo se adapta a lo que se entrena: quien quiere mejorar en una carrera de 5 kilómetros debe correr distancias largas, no solo levantar pesas.<br><br>El principio de individualidad recuerda que cada persona responde distinto al mismo entrenamiento, según su edad, su experiencia y su estado físico. El principio de recuperación señala que el cuerpo se fortalece durante el descanso: sin dormir bien, hidratarse y alimentarse, el entrenamiento produce fatiga en lugar de mejoras. Finalmente, el principio de continuidad advierte que los beneficios se pierden si se abandona la práctica durante semanas; es mejor entrenar tres veces por semana todo el año que siete veces durante un mes y luego dejarlo."}, {"id": 2, "titulo": "La sesión y la frecuencia cardiaca", "instruccion": "(Responda las preguntas 8 a 13 con base en el siguiente texto.)", "cuerpo": "Una sesión de entrenamiento tiene tres partes. El calentamiento (10 a 15 minutos) eleva poco a poco la temperatura del cuerpo y la frecuencia cardiaca, con trote suave, movilidad articular y ejercicios de técnica de carrera. La parte principal desarrolla el objetivo del día: por ejemplo, carrera continua, series de velocidad o saltos. La vuelta a la calma (5 a 10 minutos) baja la intensidad con trote suave, caminata y estiramientos.<br><br>La frecuencia cardiaca (FC) es el número de latidos del corazón por minuto y sirve para controlar la intensidad. Una fórmula sencilla para estimar la frecuencia cardiaca máxima es restar la edad a 220: un estudiante de 16 años tendría una FC máxima aproximada de 204 latidos por minuto. Para mejorar la resistencia aeróbica se recomienda trabajar entre el 60 % y el 80 % de esa frecuencia máxima. El pulso se puede tomar en la muñeca o en el cuello, contando los latidos durante 15 segundos y multiplicando por cuatro. Esta fórmula es una estimación: la percepción del esfuerzo y la orientación del docente también son importantes."}, {"id": 3, "titulo": "Del test al plan personal", "instruccion": "(Responda las preguntas 14 a 20 con base en el siguiente texto.)", "cuerpo": "Para diseñar un plan, primero hay que saber de dónde se parte. El test de Cooper consiste en correr la mayor distancia posible en 12 minutos y permite estimar la resistencia aeróbica. Con ese resultado, cada estudiante se plantea una meta. Una buena meta es específica, medible, alcanzable, relevante y con un tiempo definido: por ejemplo, «aumentar 200 metros mi resultado en el test de Cooper en ocho semanas», y no simplemente «estar en forma».<br><br>Un plan sencillo para un estudiante que empieza puede incluir tres sesiones por semana en días no consecutivos, con 20 a 30 minutos de carrera continua a intensidad moderada, y aumentar el tiempo de carrera de forma gradual cada semana. Es útil registrar cada sesión: fecha, duración, sensación de esfuerzo y frecuencia cardiaca. Al final del periodo, se repite el test para comparar. Integrar la actividad física al proyecto de vida significa que no depende de una nota ni de un uniforme: es una decisión personal que acompaña a la persona después del colegio."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Lexical", "enunciado": "El principio de «sobrecarga progresiva» indica que:", "opciones": {"A": "la carga del entrenamiento debe aumentar de forma gradual.", "B": "el descanso no es necesario.", "C": "todas las personas deben entrenar igual.", "D": "hay que entrenar siempre con el máximo peso posible."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una estudiante quiere mejorar su tiempo en una carrera de 5 km. Según el principio de especificidad, debería:", "opciones": {"A": "incluir carreras de distancias largas en su entrenamiento.", "B": "entrenar solo la flexibilidad.", "C": "practicar únicamente saltos.", "D": "hacer solo ejercicios de pesas."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuándo se fortalece el cuerpo?", "opciones": {"A": "Únicamente en competencias.", "B": "Cuando se entrena sin descanso.", "C": "Solo durante el entrenamiento más intenso.", "D": "Durante el descanso, con sueño, hidratación y alimentación adecuados."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué dos compañeros con el mismo plan pueden obtener resultados distintos?", "opciones": {"A": "Porque uno de ellos hizo trampa.", "B": "Porque el principio de especificidad no funciona.", "C": "Por el principio de individualidad: cada persona responde diferente.", "D": "Porque el plan estaba mal escrito."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Qué opción respeta mejor el principio de continuidad?", "opciones": {"A": "Entrenar siete veces por semana un mes y luego descansar seis meses.", "B": "Entrenar tres veces por semana durante todo el año.", "C": "Entrenar un día muy fuerte cada dos meses.", "D": "Entrenar solo antes de los exámenes de Educación Física."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Qué puede pasar si se entrena mucho sin recuperación adecuada?", "opciones": {"A": "Se elimina el riesgo de lesiones.", "B": "Se mejora el doble de rápido.", "C": "Se acumula fatiga en lugar de lograr mejoras.", "D": "No ocurre nada, el descanso es opcional."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la tesis del primer texto?", "opciones": {"A": "Solo los atletas profesionales deben entrenar con principios.", "B": "Entrenar bien requiere aplicar principios para mejorar sin lesionarse.", "C": "Cualquier ejercicio sin orden produce los mismos resultados.", "D": "El descanso es una pérdida de tiempo."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuáles son las tres partes de una sesión de entrenamiento?", "opciones": {"A": "Estiramiento, competencia y descanso.", "B": "Trote, velocidad y fuerza.", "C": "Inicio, evaluación y premiación.", "D": "Calentamiento, parte principal y vuelta a la calma."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es la FC máxima estimada de un estudiante de 16 años según la fórmula del texto?", "opciones": {"A": "204 latidos por minuto.", "B": "220 latidos por minuto.", "C": "236 latidos por minuto.", "D": "180 latidos por minuto."}}, {"n": 10, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante de 17 años quiere entrenar resistencia aeróbica entre el 60 % y el 80 % de su FC máxima. ¿Cuál es el rango aproximado?", "opciones": {"A": "Entre 100 y 120 latidos por minuto.", "B": "Entre 60 y 80 latidos por minuto.", "C": "Entre 122 y 162 latidos por minuto.", "D": "Entre 170 y 203 latidos por minuto."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Contaste 35 latidos en 15 segundos. ¿Cuál es tu frecuencia cardiaca?", "opciones": {"A": "105 latidos por minuto.", "B": "35 latidos por minuto.", "C": "70 latidos por minuto.", "D": "140 latidos por minuto."}}, {"n": 12, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la vuelta a la calma?", "opciones": {"A": "Para medir el resultado del test de Cooper.", "B": "Para bajar la intensidad gradualmente después de la parte principal.", "C": "Para reemplazar el calentamiento.", "D": "Para aumentar al máximo la frecuencia cardiaca."}}, {"n": 13, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el texto aclara que la fórmula 220 menos la edad es «una estimación»?", "opciones": {"A": "Porque la fórmula está prohibida en los colegios.", "B": "Porque la frecuencia cardiaca no tiene relación con la intensidad.", "C": "Porque cada persona es diferente y también hay que considerar la percepción del esfuerzo.", "D": "Porque solo sirve para adultos mayores."}}, {"n": 14, "seccion": 3, "competencia": "Literal", "enunciado": "¿En qué consiste el test de Cooper?", "opciones": {"A": "En correr 100 metros lo más rápido posible.", "B": "En caminar durante una hora.", "C": "En saltar la mayor distancia desde parado.", "D": "En correr la mayor distancia posible en 12 minutos."}}, {"n": 15, "seccion": 3, "competencia": "Aplicación", "enunciado": "¿Cuál de estas metas cumple las características descritas en el texto?", "opciones": {"A": "Correr mucho más.", "B": "Ser el mejor del salón.", "C": "Estar en forma este año.", "D": "Aumentar 200 metros mi resultado del test de Cooper en ocho semanas."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el plan propone sesiones en días no consecutivos?", "opciones": {"A": "Porque el test de Cooper se hace cada dos días.", "B": "Para permitir la recuperación entre sesiones.", "C": "Porque está prohibido correr dos días seguidos.", "D": "Para que el plan dure menos semanas."}}, {"n": 17, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué datos se recomienda registrar en cada sesión?", "opciones": {"A": "Fecha, duración, sensación de esfuerzo y frecuencia cardiaca.", "B": "Únicamente la nota obtenida.", "C": "Solo el nombre del compañero de entrenamiento.", "D": "El clima y la ropa usada."}}, {"n": 18, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Para qué se repite el test al final del periodo?", "opciones": {"A": "Para calcular la FC máxima.", "B": "Para comparar el resultado con el inicial y valorar el progreso.", "C": "Para cambiar de deporte.", "D": "Para reemplazar el registro de sesiones."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, integrar la actividad física al proyecto de vida significa que:", "opciones": {"A": "termina al graduarse.", "B": "solo se practica con uniforme.", "C": "es una decisión personal que continúa después del colegio.", "D": "depende de la nota de Educación Física."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué relación hay entre los tres textos?", "opciones": {"A": "Los principios, el control de la intensidad y las metas permiten construir un plan personal de entrenamiento.", "B": "Los tres afirman que el descanso no es necesario.", "C": "Los tres explican la historia del atletismo.", "D": "Los tres tratan solo sobre la frecuencia cardiaca."}}]}, {"id": "2027-g10-p2-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 2", "titulo": "Quiz — Mitos y realidades de la vida saludable (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Lo que se dice en el colegio", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto y en los recursos de Hábitos de vida saludables.)", "cuerpo": "En una encuesta rápida entre estudiantes de la media aparecieron varias frases que circulan en los descansos, en las redes sociales y hasta en el gimnasio. Algunas tienen respaldo científico y otras son mitos: creencias muy repetidas que no coinciden con lo que dicen los organismos de salud.<br><br>Para separar unas de otras sirve consultar fuentes confiables, como la Organización Mundial de la Salud (OMS) o la Academia Americana de Pediatría (AAP), que revisan la evidencia antes de dar una recomendación. En este quiz encontrarás seis de esas frases. Para cada una, elige la opción que la describe correctamente: si es un mito o una realidad, y por qué."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Aplicación", "enunciado": "«Las bebidas energizantes mejoran el rendimiento deportivo». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: la cafeína que contienen es necesaria para cualquier entrenamiento.", "B": "Realidad: reemplazan el agua y reponen todo lo que se pierde al sudar.", "C": "Mito: aportan cafeína y azúcares, no se recomiendan en adolescentes y, para la mayoría de las sesiones, basta con agua.", "D": "Mito: solo funcionan si se toman frías y antes del calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Hacer abdominales elimina la grasa del abdomen». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: no se pierde grasa localizada ejercitando una sola zona; las abdominales fortalecen el músculo.", "B": "Realidad: cada abdominal quema la grasa que está justo encima del músculo trabajado.", "C": "Realidad: basta con hacer cien abdominales diarias para reducir la cintura.", "D": "Mito: las abdominales no tienen ningún efecto sobre el cuerpo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "«Un adolescente debería acumular en promedio 60 minutos diarios de actividad física moderada a vigorosa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: la OMS recomienda solo 60 minutos a la semana.", "B": "Mito: esa recomendación es únicamente para deportistas de competencia.", "C": "Realidad, pero solo si los 60 minutos se hacen en una sola sesión sin pausas.", "D": "Realidad: es la recomendación de la OMS (2020) para niños y adolescentes de 5 a 17 años."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "«Sudar más significa que quemaste más grasa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el sudor es grasa que sale del cuerpo en forma líquida.", "B": "Mito: el sudor sirve para regular la temperatura del cuerpo; sudar más no indica que se haya quemado más grasa.", "C": "Realidad: por eso conviene entrenar con ropa plástica o muy abrigada.", "D": "Mito: sudar es una señal de que el ejercicio fue inútil."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Dormir poco no afecta el rendimiento físico ni el académico». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el cuerpo se adapta a dormir cuatro o cinco horas sin consecuencias.", "B": "Realidad: el sueño solo es importante en la infancia.", "C": "Mito: dormir poco afecta la concentración, la memoria y el rendimiento; los adolescentes necesitan de 8 a 10 horas.", "D": "Mito: dormir poco solo afecta a quienes practican deporte."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "«La hidratación solo importa en los deportes de competencia». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: en una clase de Educación Física no se pierde agua.", "B": "Realidad: solo hay que beber cuando aparece una sed muy intensa.", "C": "Mito: hidratarse solo es necesario en días de mucho calor.", "D": "Mito: hay que hidratarse antes, durante y después de cualquier actividad física, incluida la clase y el juego."}}]}, {"id": "2027-g10-p3-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 3", "titulo": "Quiz — Chequeo saludable: actividad física, nutrición, hidratación y descanso (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 12, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Cuatro hábitos que sostienen la salud", "instruccion": "(Responda las preguntas 1 a 8 con base en el siguiente texto.)", "cuerpo": "<b>Actividad física.</b> Según las directrices de la Organización Mundial de la Salud (OMS, 2020), los niños y adolescentes de 5 a 17 años deberían acumular en promedio 60 minutos diarios de actividad física de intensidad moderada a vigorosa, en su mayoría aeróbica. Al menos tres días por semana conviene incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. También recomienda limitar el tiempo sedentario, en especial el que se pasa frente a pantallas por diversión.<br><br><b>Nutrición.</b> La OMS señala que una alimentación saludable incluye frutas, verduras, legumbres y cereales integrales. A partir de los 10 años se recomienda consumir al menos 400 gramos de frutas y verduras al día. Los azúcares libres —los que se añaden a bebidas y alimentos, y los de jugos y mieles— deberían ser menos del 10 % de la energía diaria, e idealmente menos del 5 %. También aconseja reducir la sal.<br><br><b>Hidratación.</b> La Academia Americana de Pediatría (AAP) explica que el agua es la mejor bebida para la mayoría de las actividades físicas de niños y adolescentes. Las bebidas deportivas, que aportan azúcares y electrolitos, solo pueden ayudar en actividades vigorosas y prolongadas. Las bebidas energizantes son otro producto: contienen cafeína y otros estimulantes, y los niños y adolescentes no deberían consumirlas.<br><br><b>Descanso.</b> La AAP apoya las pautas de la Academia Estadounidense de Medicina del Sueño: los adolescentes de 13 a 18 años necesitan de 8 a 10 horas de sueño en cada periodo de 24 horas. Dormir lo suficiente se relaciona con mejor memoria, comportamiento, rendimiento académico y salud mental; dormir poco se asocia con dificultades para concentrarse, dolores de cabeza y otros problemas de salud."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánta actividad física recomienda la OMS a los adolescentes?", "opciones": {"A": "60 minutos a la semana, solo en la clase de Educación Física.", "B": "En promedio 60 minutos diarios de intensidad moderada a vigorosa.", "C": "Dos horas diarias de ejercicio de fuerza.", "D": "30 minutos de caminata suave, tres veces por semana."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Camila juega videojuegos cuatro horas al día y solo se mueve en la clase de Educación Física. Según la OMS, ¿qué le convendría cambiar primero?", "opciones": {"A": "Reducir el tiempo frente a la pantalla y sumar actividad física moderada a vigorosa casi todos los días.", "B": "Nada, porque la clase de Educación Física ya cubre lo recomendado.", "C": "Hacer ejercicio solo el fin de semana durante varias horas seguidas.", "D": "Cambiar los videojuegos por series de televisión."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué cantidad mínima de frutas y verduras al día recomienda la OMS a partir de los 10 años?", "opciones": {"A": "100 gramos.", "B": "200 gramos.", "C": "400 gramos.", "D": "Una sola fruta a la semana."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «azúcares libres» se refiere a:", "opciones": {"A": "el azúcar que contienen las frutas enteras y las verduras.", "B": "los alimentos que no tienen ningún tipo de azúcar.", "C": "los carbohidratos de los cereales integrales.", "D": "los azúcares que se añaden a bebidas y alimentos, y los de jugos y mieles."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según la AAP, ¿cuál es la mejor bebida para la mayoría de las actividades físicas de los adolescentes?", "opciones": {"A": "Una bebida energizante.", "B": "El agua.", "C": "Una gaseosa.", "D": "Una bebida deportiva en cualquier sesión."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto distingue entre bebidas deportivas y bebidas energizantes?", "opciones": {"A": "Porque las energizantes contienen cafeína y estimulantes que los adolescentes no deberían consumir.", "B": "Porque las energizantes hidratan mejor que el agua.", "C": "Porque las deportivas están prohibidas para menores de edad.", "D": "Porque ambas son iguales y solo cambia el sabor."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas horas de sueño necesitan los adolescentes de 13 a 18 años?", "opciones": {"A": "De 5 a 6 horas.", "B": "De 6 a 7 horas.", "C": "De 11 a 14 horas.", "D": "De 8 a 10 horas."}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Andrés se acuesta a la 1:00 a. m. para terminar tareas y se levanta a las 5:30 a. m. ¿Qué conclusión es coherente con el texto?", "opciones": {"A": "Su horario es adecuado porque aprovecha mejor el tiempo.", "B": "Dormir poco solo le afectará si practica deporte.", "C": "Duerme menos de lo recomendado, lo que puede afectar su concentración, su memoria y su rendimiento.", "D": "Puede recuperar todo el sueño perdido durmiendo una siesta corta."}}]}, {"id": "2027-g11-p2-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 2", "titulo": "Quiz — Mitos y realidades de la vida saludable (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Lo que se dice en el colegio", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto y en los recursos de Hábitos de vida saludables.)", "cuerpo": "En una encuesta rápida entre estudiantes de la media aparecieron varias frases que circulan en los descansos, en las redes sociales y hasta en el gimnasio. Algunas tienen respaldo científico y otras son mitos: creencias muy repetidas que no coinciden con lo que dicen los organismos de salud.<br><br>Para separar unas de otras sirve consultar fuentes confiables, como la Organización Mundial de la Salud (OMS) o la Academia Americana de Pediatría (AAP), que revisan la evidencia antes de dar una recomendación. En este quiz encontrarás seis de esas frases. Para cada una, elige la opción que la describe correctamente: si es un mito o una realidad, y por qué."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Aplicación", "enunciado": "«Las bebidas energizantes mejoran el rendimiento deportivo». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: la cafeína que contienen es necesaria para cualquier entrenamiento.", "B": "Realidad: reemplazan el agua y reponen todo lo que se pierde al sudar.", "C": "Mito: aportan cafeína y azúcares, no se recomiendan en adolescentes y, para la mayoría de las sesiones, basta con agua.", "D": "Mito: solo funcionan si se toman frías y antes del calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Hacer abdominales elimina la grasa del abdomen». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: no se pierde grasa localizada ejercitando una sola zona; las abdominales fortalecen el músculo.", "B": "Realidad: cada abdominal quema la grasa que está justo encima del músculo trabajado.", "C": "Realidad: basta con hacer cien abdominales diarias para reducir la cintura.", "D": "Mito: las abdominales no tienen ningún efecto sobre el cuerpo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "«Un adolescente debería acumular en promedio 60 minutos diarios de actividad física moderada a vigorosa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: la OMS recomienda solo 60 minutos a la semana.", "B": "Mito: esa recomendación es únicamente para deportistas de competencia.", "C": "Realidad, pero solo si los 60 minutos se hacen en una sola sesión sin pausas.", "D": "Realidad: es la recomendación de la OMS (2020) para niños y adolescentes de 5 a 17 años."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "«Sudar más significa que quemaste más grasa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el sudor es grasa que sale del cuerpo en forma líquida.", "B": "Mito: el sudor sirve para regular la temperatura del cuerpo; sudar más no indica que se haya quemado más grasa.", "C": "Realidad: por eso conviene entrenar con ropa plástica o muy abrigada.", "D": "Mito: sudar es una señal de que el ejercicio fue inútil."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Dormir poco no afecta el rendimiento físico ni el académico». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el cuerpo se adapta a dormir cuatro o cinco horas sin consecuencias.", "B": "Realidad: el sueño solo es importante en la infancia.", "C": "Mito: dormir poco afecta la concentración, la memoria y el rendimiento; los adolescentes necesitan de 8 a 10 horas.", "D": "Mito: dormir poco solo afecta a quienes practican deporte."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "«La hidratación solo importa en los deportes de competencia». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: en una clase de Educación Física no se pierde agua.", "B": "Realidad: solo hay que beber cuando aparece una sed muy intensa.", "C": "Mito: hidratarse solo es necesario en días de mucho calor.", "D": "Mito: hay que hidratarse antes, durante y después de cualquier actividad física, incluida la clase y el juego."}}]}, {"id": "2027-g11-p3-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 3", "titulo": "Quiz — Chequeo saludable: actividad física, nutrición, hidratación y descanso (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 12, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Cuatro hábitos que sostienen la salud", "instruccion": "(Responda las preguntas 1 a 8 con base en el siguiente texto.)", "cuerpo": "<b>Actividad física.</b> Según las directrices de la Organización Mundial de la Salud (OMS, 2020), los niños y adolescentes de 5 a 17 años deberían acumular en promedio 60 minutos diarios de actividad física de intensidad moderada a vigorosa, en su mayoría aeróbica. Al menos tres días por semana conviene incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. También recomienda limitar el tiempo sedentario, en especial el que se pasa frente a pantallas por diversión.<br><br><b>Nutrición.</b> La OMS señala que una alimentación saludable incluye frutas, verduras, legumbres y cereales integrales. A partir de los 10 años se recomienda consumir al menos 400 gramos de frutas y verduras al día. Los azúcares libres —los que se añaden a bebidas y alimentos, y los de jugos y mieles— deberían ser menos del 10 % de la energía diaria, e idealmente menos del 5 %. También aconseja reducir la sal.<br><br><b>Hidratación.</b> La Academia Americana de Pediatría (AAP) explica que el agua es la mejor bebida para la mayoría de las actividades físicas de niños y adolescentes. Las bebidas deportivas, que aportan azúcares y electrolitos, solo pueden ayudar en actividades vigorosas y prolongadas. Las bebidas energizantes son otro producto: contienen cafeína y otros estimulantes, y los niños y adolescentes no deberían consumirlas.<br><br><b>Descanso.</b> La AAP apoya las pautas de la Academia Estadounidense de Medicina del Sueño: los adolescentes de 13 a 18 años necesitan de 8 a 10 horas de sueño en cada periodo de 24 horas. Dormir lo suficiente se relaciona con mejor memoria, comportamiento, rendimiento académico y salud mental; dormir poco se asocia con dificultades para concentrarse, dolores de cabeza y otros problemas de salud."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánta actividad física recomienda la OMS a los adolescentes?", "opciones": {"A": "60 minutos a la semana, solo en la clase de Educación Física.", "B": "En promedio 60 minutos diarios de intensidad moderada a vigorosa.", "C": "Dos horas diarias de ejercicio de fuerza.", "D": "30 minutos de caminata suave, tres veces por semana."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Camila juega videojuegos cuatro horas al día y solo se mueve en la clase de Educación Física. Según la OMS, ¿qué le convendría cambiar primero?", "opciones": {"A": "Reducir el tiempo frente a la pantalla y sumar actividad física moderada a vigorosa casi todos los días.", "B": "Nada, porque la clase de Educación Física ya cubre lo recomendado.", "C": "Hacer ejercicio solo el fin de semana durante varias horas seguidas.", "D": "Cambiar los videojuegos por series de televisión."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué cantidad mínima de frutas y verduras al día recomienda la OMS a partir de los 10 años?", "opciones": {"A": "100 gramos.", "B": "200 gramos.", "C": "400 gramos.", "D": "Una sola fruta a la semana."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «azúcares libres» se refiere a:", "opciones": {"A": "el azúcar que contienen las frutas enteras y las verduras.", "B": "los alimentos que no tienen ningún tipo de azúcar.", "C": "los carbohidratos de los cereales integrales.", "D": "los azúcares que se añaden a bebidas y alimentos, y los de jugos y mieles."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según la AAP, ¿cuál es la mejor bebida para la mayoría de las actividades físicas de los adolescentes?", "opciones": {"A": "Una bebida energizante.", "B": "El agua.", "C": "Una gaseosa.", "D": "Una bebida deportiva en cualquier sesión."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto distingue entre bebidas deportivas y bebidas energizantes?", "opciones": {"A": "Porque las energizantes contienen cafeína y estimulantes que los adolescentes no deberían consumir.", "B": "Porque las energizantes hidratan mejor que el agua.", "C": "Porque las deportivas están prohibidas para menores de edad.", "D": "Porque ambas son iguales y solo cambia el sabor."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas horas de sueño necesitan los adolescentes de 13 a 18 años?", "opciones": {"A": "De 5 a 6 horas.", "B": "De 6 a 7 horas.", "C": "De 11 a 14 horas.", "D": "De 8 a 10 horas."}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Andrés se acuesta a la 1:00 a. m. para terminar tareas y se levanta a las 5:30 a. m. ¿Qué conclusión es coherente con el texto?", "opciones": {"A": "Su horario es adecuado porque aprovecha mejor el tiempo.", "B": "Dormir poco solo le afectará si practica deporte.", "C": "Duerme menos de lo recomendado, lo que puede afectar su concentración, su memoria y su rendimiento.", "D": "Puede recuperar todo el sueño perdido durmiendo una siesta corta."}}]}, {"id": "2027-g6-p2-quiz1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Habilidades motrices: moverse con control (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Habilidades motrices: moverse con control", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las habilidades motrices básicas son los movimientos que el cuerpo aprende para desenvolverse en el juego y en el deporte. Se agrupan en tres tipos. Las habilidades locomotrices llevan el cuerpo de un lugar a otro: caminar, correr, saltar, galopar y deslizarse. Las habilidades manipulativas trabajan con objetos: lanzar, atrapar, golpear, patear y conducir un balón. Las habilidades de equilibrio o estabilidad permiten mantener el cuerpo controlado, ya sea quieto (equilibrio estático) o en movimiento (equilibrio dinámico), como al girar o al caminar sobre una línea.<br><br>Estas habilidades no se aprenden de un día para otro: mejoran con la práctica repetida, primero en situaciones sencillas y luego en juegos con más compañeros y reglas. Por eso en las clases se usan los juegos predeportivos, que son juegos con reglas simples que preparan al estudiante para un deporte sin exigirle todavía la técnica completa."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, las habilidades locomotrices sirven para:", "opciones": {"A": "trabajar únicamente con objetos.", "B": "llevar el cuerpo de un lugar a otro.", "C": "mantener el cuerpo siempre quieto.", "D": "cambiar las reglas del juego."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál de las siguientes es una habilidad manipulativa?", "opciones": {"A": "Lanzar y atrapar un balón.", "B": "Galopar.", "C": "Mantenerse en un solo pie.", "D": "Deslizarse hacia un lado."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "El equilibrio dinámico ocurre cuando el cuerpo:", "opciones": {"A": "permanece completamente quieto.", "B": "se mantiene controlado mientras se mueve.", "C": "pierde el control al girar.", "D": "se apoya siempre en un compañero."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «predeportivos» se refiere a juegos que:", "opciones": {"A": "preparan para un deporte con reglas simples.", "B": "reemplazan a los deportes oficiales.", "C": "solo se juegan en competencias.", "D": "exigen la técnica completa desde el inicio."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se practica primero en situaciones sencillas y luego en juegos con más compañeros?", "opciones": {"A": "Porque los compañeros estorban al principio.", "B": "Porque el aprendizaje avanza de lo fácil a lo complejo.", "C": "Porque las reglas solo se usan al final.", "D": "Porque las habilidades se aprenden de un día para otro."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante pierde el control cuando gira sobre una línea de equilibrio. ¿Qué habilidad debe reforzar?", "opciones": {"A": "El equilibrio dinámico.", "B": "El lanzamiento de precisión.", "C": "El galope.", "D": "La conducción de balón con el pie."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para practicar una habilidad manipulativa en parejas, la actividad más adecuada es:", "opciones": {"A": "correr dos vueltas sin parar.", "B": "quedarse quieto con los ojos cerrados.", "C": "pasarse un balón con ambas manos a distintas distancias.", "D": "saltar la cuerda sin ningún objeto."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, las habilidades mejoran con la práctica repetida. Si un estudiante practica una sola vez, lo más probable es que:", "opciones": {"A": "la domine por completo.", "B": "pase a jugar un deporte oficial.", "C": "ya no necesite las reglas.", "D": "no consolide la habilidad."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "El texto clasifica las habilidades motrices básicas en:", "opciones": {"A": "rápidas y lentas.", "B": "de fuerza, resistencia y velocidad.", "C": "locomotrices, manipulativas y de equilibrio.", "D": "una distinta por cada deporte."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "El equilibrio es la única habilidad importante.", "B": "Los juegos con reglas simples no sirven para aprender.", "C": "Las habilidades motrices se tienen desde el nacimiento y no se entrenan.", "D": "Las habilidades motrices se aprenden con la práctica y se agrupan en tres tipos que se aplican en el juego."}}]}, {"id": "2027-g6-p2-quiz2", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Minifútbol y minibaloncesto: reglas básicas (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Minifútbol y minibaloncesto: reglas básicas", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En la clase de Educación Física se practican versiones reducidas de los deportes para que todos jueguen más. El minifútbol se juega entre equipos pequeños, por lo general de cuatro o cinco jugadores, en una cancha más corta que la de fútbol. El balón se juega con los pies y no se puede tocar con las manos, salvo el portero dentro de su área. Se anota un gol cuando el balón cruza completamente la línea de la portería. Son faltas empujar, hacer zancadilla, agarrar al rival y jugar el balón con la mano; la sanción es un tiro libre para el equipo contrario. Cuando el balón sale por una línea lateral, se reanuda con un saque de banda.<br><br>El minibaloncesto 3 contra 3 se juega en media cancha, con un solo aro. Se avanza con el balón botándolo con una mano; si el jugador lo agarra con las dos manos y vuelve a botarlo, comete doble drible, y si camina con el balón sin botarlo, comete pasos. Cada canasta vale un punto, o dos si se lanza desde detrás del arco. Las faltas personales —empujar, golpear o agarrar— se sancionan con la posesión para el equipo contrario. En ambos deportes, el juego limpio significa respetar las reglas, a los compañeros y al árbitro, aunque este sea un estudiante."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuántos jugadores tiene por lo general un equipo de minifútbol?", "opciones": {"A": "Cuatro o cinco.", "B": "Siete u ocho.", "C": "Dos o tres.", "D": "Once."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuándo se anota un gol?", "opciones": {"A": "Cuando el balón toca el poste.", "B": "Cuando el balón cruza completamente la línea de la portería.", "C": "Cuando el portero suelta el balón.", "D": "Cuando el balón toca la línea lateral."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se reanuda el juego cuando el balón sale por una línea lateral?", "opciones": {"A": "Con un saque de banda.", "B": "Con un tiro libre directo.", "C": "Con un penal.", "D": "Con un salto entre dos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «doble drible» significa:", "opciones": {"A": "agarrar el balón con las dos manos y volver a botarlo.", "B": "botar el balón con una sola mano.", "C": "lanzar dos veces seguidas al aro.", "D": "pasar el balón a dos compañeros."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en la clase se practican versiones reducidas de los deportes?", "opciones": {"A": "Para que los deportes sean más difíciles.", "B": "Para eliminar al árbitro.", "C": "Para que solo jueguen los mejores.", "D": "Para que todos jueguen más y participen."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un 3 contra 3, una jugadora agarra el balón con las dos manos y vuelve a botarlo. ¿Qué falta comete?", "opciones": {"A": "Pasos.", "B": "Falta personal.", "C": "Ninguna.", "D": "Doble drible."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "En minifútbol, un jugador que no es portero toca el balón con la mano. ¿Qué se sanciona?", "opciones": {"A": "Un gol para su equipo.", "B": "Un saque de banda para él.", "C": "Un tiro libre para el equipo contrario.", "D": "Nada."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto vale una canasta lanzada desde detrás del arco, según el texto?", "opciones": {"A": "Un punto.", "B": "Dos puntos.", "C": "Tres puntos.", "D": "Cinco puntos."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué una falta personal se sanciona con la posesión para el equipo contrario?", "opciones": {"A": "Porque así se premia al que empuja.", "B": "Porque el juego se hace más lento.", "C": "Porque el reglamento protege la seguridad y evita ventajas por juego brusco.", "D": "Porque en la clase no hay árbitro."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿qué significa jugar limpio?", "opciones": {"A": "Ganar a cualquier costo.", "B": "Respetar las reglas, a los compañeros y al árbitro.", "C": "Discutir todas las decisiones.", "D": "Evitar a los compañeros menos hábiles."}}]}, {"id": "2027-g6-p2-taller", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Capacidades físicomotrices y test (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Velocidad, agilidad y fuerza: tres capacidades en juego", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Las capacidades físicomotrices son las que permiten que el cuerpo se mueva con eficacia. La velocidad es la capacidad de reaccionar y desplazarse en el menor tiempo posible; se nota al salir corriendo ante una señal o al llegar primero a un balón. La agilidad es la facilidad para cambiar de dirección o de posición sin perder el control, como al esquivar en un juego de persecución. La fuerza es la capacidad de vencer una resistencia; en las piernas se manifiesta como potencia al saltar.<br><br>Estas capacidades se desarrollan jugando: los juegos de persecución, los relevos y los saltos mejoran a la vez la velocidad, la agilidad y la fuerza. Cada estudiante avanza a su propio ritmo; lo importante no es ser el más rápido, sino mejorar frente a sí mismo. Por eso, antes de cada trabajo se hace un calentamiento y, al final, una vuelta a la calma para recuperar el cuerpo."}, {"id": 2, "titulo": "Cómo se hace el test de velocidad y salto", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "En la clase se miden dos capacidades con pruebas sencillas. La primera es la velocidad, con una carrera de 30 metros. El estudiante se ubica detrás de la línea de salida, con un pie adelante; al escuchar la señal corre lo más rápido que puede hasta cruzar la línea de meta, y un compañero registra el tiempo con un cronómetro.<br><br>La segunda es el salto largo sin impulso, que mide la potencia de las piernas: el estudiante se pone detrás de una línea con los pies separados, flexiona las rodillas, balancea los brazos y salta hacia adelante con los dos pies a la vez. Se mide la distancia desde la línea hasta el punto de contacto más cercano al cuerpo; se hacen dos intentos y se anota el mejor. Para que los resultados sirvan, cada prueba se hace con calentamiento previo, en el mismo lugar y con las mismas indicaciones. Los datos se anotan en una ficha personal."}, {"id": 3, "titulo": "Interpretar mis resultados", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Después de aplicar el test, el trabajo continúa en el aula. Con la ficha personal, cada estudiante construye una tabla con sus datos: el tiempo de los 30 metros y la distancia del salto. Luego puede compararlos con las mediciones siguientes y ver si mejoraron. Interpretar un resultado significa preguntarse qué dice sobre el propio cuerpo: un tiempo menor en la carrera indica mayor velocidad, y una distancia mayor en el salto indica más potencia en las piernas.<br><br>También es importante preguntarse por qué: dormir poco, no calentar o no practicar pueden afectar el resultado. A partir de las conclusiones, cada estudiante propone una meta realista —por ejemplo, mejorar el salto en cinco centímetros— y las actividades que hará para alcanzarla. Comparar los resultados con los de otros compañeros no sirve para juzgar, porque cada cuerpo parte de condiciones diferentes."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué es la agilidad?", "opciones": {"A": "La capacidad de vencer una resistencia.", "B": "La capacidad de moverse en el menor tiempo posible.", "C": "La facilidad para cambiar de dirección o de posición sin perder el control.", "D": "La capacidad de mantener un esfuerzo largo."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se manifiesta la fuerza en las piernas?", "opciones": {"A": "Como velocidad de reacción.", "B": "Como flexibilidad.", "C": "Como equilibrio estático.", "D": "Como potencia al saltar."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En la frase «vencer una resistencia», la palabra «resistencia» se refiere a:", "opciones": {"A": "el cansancio al final de una carrera.", "B": "el tiempo que dura un juego.", "C": "el calentamiento previo.", "D": "la fuerza o carga que se opone a un movimiento."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué los juegos de persecución mejoran varias capacidades a la vez?", "opciones": {"A": "Porque exigen reaccionar, cambiar de dirección e impulsarse con las piernas.", "B": "Porque se juegan sin moverse.", "C": "Porque no tienen reglas.", "D": "Porque solo trabajan la flexibilidad."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para mejorar la agilidad, la actividad más adecuada es:", "opciones": {"A": "caminar en línea recta.", "B": "un recorrido de conos con cambios de dirección.", "C": "permanecer sentado.", "D": "levantar un objeto pesado una sola vez."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero llegó de último en una carrera, pero ahora corre más rápido que hace un mes. Según el texto, su resultado:", "opciones": {"A": "es un avance, porque lo importante es mejorar frente a sí mismo.", "B": "no tiene ningún valor.", "C": "indica que debe dejar la actividad.", "D": "es peor que el de los demás."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué se hace una vuelta a la calma al final del trabajo?", "opciones": {"A": "Para empezar otra carrera.", "B": "Para recuperar el cuerpo después del esfuerzo.", "C": "Para eliminar el calentamiento.", "D": "Para medir la velocidad."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántos metros mide la carrera de velocidad del test?", "opciones": {"A": "30 metros.", "B": "50 metros.", "C": "100 metros.", "D": "400 metros."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántos intentos se hacen en el salto largo sin impulso y cuál se anota?", "opciones": {"A": "Un intento, y se anota ese.", "B": "Dos intentos, y se anota el mejor.", "C": "Tres intentos, y se promedian.", "D": "Cinco intentos, y se anota el último."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la palabra «potencia» se refiere a:", "opciones": {"A": "el descanso entre intentos.", "B": "el cansancio de las piernas.", "C": "el equilibrio al caer.", "D": "la fuerza aplicada con rapidez."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué cada prueba se hace en el mismo lugar y con las mismas indicaciones?", "opciones": {"A": "Para que los resultados se puedan comparar entre una medición y otra.", "B": "Para que la prueba dure más.", "C": "Para que todos saquen la misma nota.", "D": "Para evitar el calentamiento."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "En la carrera de 30 metros, ¿qué debe hacer el estudiante al escuchar la señal?", "opciones": {"A": "Esperar a que corran los demás.", "B": "Correr lo más rápido posible hasta cruzar la meta.", "C": "Caminar hasta la meta.", "D": "Saltar sin correr."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "En el salto largo sin impulso, un estudiante cae con un solo pie. ¿Qué debe corregir?", "opciones": {"A": "Caer siempre con un solo pie.", "B": "Saltar de espaldas.", "C": "Tomar impulso con una carrera.", "D": "Saltar y caer con los dos pies a la vez."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué utilidad tiene anotar los datos en una ficha personal?", "opciones": {"A": "Sirve para presumir ante los compañeros.", "B": "Reemplaza la prueba.", "C": "Permite comparar el progreso propio con mediciones posteriores.", "D": "No tiene ninguna utilidad."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué se construye con los datos de la ficha personal?", "opciones": {"A": "Una tabla con el tiempo de la carrera y la distancia del salto.", "B": "Un reglamento.", "C": "Un partido.", "D": "Un mapa del colegio."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, «interpretar» un resultado significa:", "opciones": {"A": "ocultarlo.", "B": "repetir la prueba.", "C": "explicar qué dice sobre el propio cuerpo.", "D": "compararlo con el de otro."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué comparar los resultados con los de otros compañeros no sirve para juzgar?", "opciones": {"A": "Porque todos los cuerpos son iguales.", "B": "Porque está prohibido anotar datos.", "C": "Porque no existen datos.", "D": "Porque cada cuerpo parte de condiciones diferentes."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un estudiante mejoró de 8,0 a 7,5 segundos en los 30 metros. ¿Qué indica ese cambio?", "opciones": {"A": "Que disminuyó su velocidad.", "B": "Que empeoró su salto.", "C": "Que aumentó su velocidad.", "D": "Que no cambió su condición."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál de estas es una meta realista?", "opciones": {"A": "Saltar el doble en una semana.", "B": "Mejorar el salto en cinco centímetros con práctica regular.", "C": "Superar al mejor del curso en un día.", "D": "Dejar de practicar para no cansarse."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando las tres lecturas, un buen proceso con el test físico incluye:", "opciones": {"A": "medir una vez y olvidar los datos.", "B": "comparar para decidir quién es mejor.", "C": "medir con cuidado, interpretar los resultados y proponer metas propias para mejorar.", "D": "evitar el calentamiento para ahorrar tiempo."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g7-p2-quiz1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Las capacidades físicas básicas (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Las capacidades físicas básicas", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las capacidades físicas básicas son cuatro: fuerza, resistencia, velocidad y flexibilidad. La fuerza es la capacidad de vencer una resistencia o una carga, por ejemplo, al saltar, empujar o cargar un peso. La resistencia permite mantener un esfuerzo durante un tiempo prolongado sin cansarse demasiado, como al trotar quince minutos. La velocidad es la capacidad de realizar un movimiento o recorrer una distancia en el menor tiempo posible. La flexibilidad es la amplitud con la que se pueden mover las articulaciones y estirar los músculos.<br><br>Estas capacidades no se desarrollan igual en todas las personas ni al mismo ritmo: dependen de la edad, de los hábitos y de la práctica regular. Un buen calentamiento prepara el cuerpo para trabajarlas sin lesiones, y la vuelta a la calma ayuda a recuperarse. Por eso, antes de pensar en jugar un partido, conviene conocer qué capacidades se necesitan y cómo se entrenan."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas capacidades físicas básicas menciona el texto?", "opciones": {"A": "Cuatro.", "B": "Dos.", "C": "Seis.", "D": "Tres."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "La resistencia permite:", "opciones": {"A": "recorrer una distancia en el menor tiempo posible.", "B": "estirar los músculos con amplitud.", "C": "vencer una carga máxima en un solo intento.", "D": "mantener un esfuerzo durante un tiempo prolongado."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "La flexibilidad es la capacidad de:", "opciones": {"A": "cargar un peso elevado.", "B": "correr muy rápido.", "C": "mantener el esfuerzo por mucho tiempo.", "D": "mover las articulaciones con gran amplitud."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «amplitud» significa:", "opciones": {"A": "rapidez de reacción.", "B": "fuerza máxima.", "C": "extensión o rango de un movimiento.", "D": "cansancio acumulado."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué las capacidades no se desarrollan igual en todas las personas?", "opciones": {"A": "Porque el calentamiento no existe.", "B": "Porque dependen de la edad, los hábitos y la práctica regular.", "C": "Porque solo los atletas las tienen.", "D": "Porque la flexibilidad no se puede entrenar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante quiere mejorar su resistencia. ¿Qué actividad es más adecuada?", "opciones": {"A": "Hacer un solo salto largo.", "B": "Trotar de forma continua a un ritmo cómodo.", "C": "Levantar el máximo peso una vez.", "D": "Quedarse quieto mucho tiempo."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de trabajar la velocidad, lo correcto es:", "opciones": {"A": "correr a máxima velocidad sin calentar.", "B": "estirar de forma brusca.", "C": "hacer un calentamiento que prepare músculos y articulaciones.", "D": "beber mucha agua de golpe."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la vuelta a la calma?", "opciones": {"A": "Para ayudar al cuerpo a recuperarse después del esfuerzo.", "B": "Para aumentar la intensidad del ejercicio.", "C": "Para reemplazar el calentamiento.", "D": "Para medir el rendimiento."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, la fuerza se evidencia al:", "opciones": {"A": "saltar, empujar o cargar un peso.", "B": "trotar quince minutos.", "C": "estirar los brazos.", "D": "cambiar de dirección."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "Solo la fuerza es importante.", "B": "Las capacidades físicas básicas son cuatro y se desarrollan con práctica regular y calentamiento.", "C": "Las capacidades físicas no se pueden mejorar.", "D": "El calentamiento es opcional."}}]}, {"id": "2027-g7-p2-quiz2", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Minivoleibol: reglamento básico (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Minivoleibol: reglamento básico", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El minivoleibol es una versión del voleibol adaptada a la clase: se juega en una cancha pequeña, con la red más baja y equipos de cuatro jugadores. Cada jugada se inicia con un saque desde detrás de la línea de fondo. Un equipo puede tocar el balón hasta tres veces antes de pasarlo al otro lado, y un mismo jugador no puede golpearlo dos veces seguidas. Los golpes básicos son el voleo (toque de dedos por encima de la frente), el antebrazo (para recibir) y el saque.<br><br>Cuando un equipo recupera el saque, sus jugadores rotan una posición en el sentido de las manecillas del reloj, de modo que todos pasan por todas las posiciones. En la clase, cada jugada gana un punto, y el set se juega a 15 puntos con diferencia de dos. Son faltas tocar la red, el doble toque, retener el balón y enviarlo fuera de la cancha. Un balón que cae sobre la línea es válido."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuántos jugadores tiene un equipo de minivoleibol?", "opciones": {"A": "Seis.", "B": "Dos.", "C": "Once.", "D": "Cuatro."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos toques puede dar un equipo antes de pasar el balón al otro lado?", "opciones": {"A": "Hasta tres.", "B": "Hasta dos.", "C": "Hasta cuatro.", "D": "Solo uno."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué sentido rotan los jugadores al recuperar el saque?", "opciones": {"A": "En sentido contrario a las manecillas.", "B": "En el sentido de las manecillas del reloj.", "C": "De un lado a otro de la red.", "D": "No rotan nunca."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el «voleo» es:", "opciones": {"A": "el toque de dedos por encima de la frente.", "B": "el saque desde la línea de fondo.", "C": "el golpe de antebrazos.", "D": "el golpe con el pie."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en la clase se baja la red y se reduce la cancha?", "opciones": {"A": "Para volver el juego imposible.", "B": "Porque la red pesa demasiado.", "C": "Para adaptar el juego y facilitar la participación de todos.", "D": "Para que haya menos jugadores."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador golpea el balón dos veces seguidas. ¿Qué se sanciona?", "opciones": {"A": "Doble toque.", "B": "Retención.", "C": "Toque de red.", "D": "Nada."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "El marcador está 14 a 14 en un set a 15 puntos. ¿Qué sucede?", "opciones": {"A": "El set termina empatado.", "B": "Gana el equipo que sacó último.", "C": "Se juega un solo punto más.", "D": "El set continúa hasta que un equipo tenga ventaja de dos puntos."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se considera un balón que cae sobre la línea?", "opciones": {"A": "Fuera.", "B": "Válido.", "C": "Nulo.", "D": "Se repite la jugada."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la rotación, según el texto?", "opciones": {"A": "Para cansar al equipo rival.", "B": "Para evitar el saque.", "C": "Para que todos los jugadores pasen por todas las posiciones.", "D": "Para eliminar jugadores."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un jugador no está de acuerdo con una falta que se le pitó. ¿Cuál es la actitud más adecuada?", "opciones": {"A": "Discutir hasta que cambie la decisión.", "B": "Aceptar la decisión y seguir jugando con respeto.", "C": "Abandonar el juego.", "D": "Culpar a un compañero."}}]}, {"id": "2027-g7-p2-taller", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Capacidades físicas: concepto y medición (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Fuerza y resistencia: dos caras del esfuerzo", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "La fuerza y la resistencia suelen confundirse, pero se entrenan de manera distinta. La fuerza se desarrolla con ejercicios en los que el cuerpo vence una carga: sentadillas, flexiones de brazos, saltos o ejercicios con el propio peso corporal. Se trabajan series cortas con pausas de descanso y buena técnica. La resistencia aeróbica, en cambio, se entrena con esfuerzos continuos y moderados, como trotar, caminar rápido o montar bicicleta, de modo que el corazón y los pulmones se adapten a trabajar durante más tiempo.<br><br>Una forma sencilla de controlar la intensidad es la prueba del habla: si se puede conversar mientras se trota, el ritmo es adecuado; si no se puede pronunciar una frase completa, la intensidad es demasiado alta. En los juegos deportivos, la resistencia ayuda a mantener el rendimiento hasta el final del partido y la fuerza permite saltar, empujar o disparar con potencia. Aumentar la carga poco a poco y descansar lo necesario evita lesiones y mejora los resultados."}, {"id": 2, "titulo": "Velocidad y flexibilidad", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "La velocidad no es solo correr rápido: también incluye reaccionar a tiempo ante una señal, como el silbato del árbitro, y cambiar de dirección con agilidad. Se entrena con carreras cortas de máximo esfuerzo y descansos largos, para que el cuerpo recupere energía y cada repetición sea realmente rápida.<br><br>La flexibilidad, por su parte, se trabaja estirando los músculos de forma suave, sin rebotes, manteniendo cada posición entre diez y treinta segundos. Antes de la actividad se recomiendan movimientos dinámicos, como círculos de brazos o balanceos de piernas, que preparan las articulaciones; los estiramientos prolongados se dejan para el final, cuando los músculos están calientes. Una buena flexibilidad permite moverse con mayor amplitud, mejora la postura y reduce el riesgo de lesiones. Sin embargo, forzar un estiramiento hasta sentir dolor no mejora la flexibilidad y puede causar daño."}, {"id": 3, "titulo": "La batería de test físicos", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Para conocer cómo están sus capacidades físicas, los estudiantes realizan una batería de test, es decir, un conjunto de pruebas aplicadas en una misma jornada. En esta clase se usan cuatro: el salto largo sin impulso mide la fuerza de las piernas; las abdominales en un minuto miden la resistencia muscular del abdomen; el sit and reach, o flexión de tronco sentado, mide la flexibilidad de la espalda baja y de la parte trasera de las piernas; y la carrera de 30 metros mide la velocidad.<br><br>Primero se hace un calentamiento general y se explica cada prueba con una demostración. Después se rota por estaciones y un compañero anota los resultados en la ficha. Medir las capacidades permite conocer el punto de partida y comprobar, con una segunda medición llamada retest, si el trabajo realizado dio resultado. Una prueba no mide a la persona, sino el estado de una capacidad en un momento determinado."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿con qué se desarrolla la fuerza?", "opciones": {"A": "Con esfuerzos continuos y suaves.", "B": "Con estiramientos prolongados.", "C": "Con ejercicios en los que el cuerpo vence una carga.", "D": "Únicamente con partidos."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué ejemplos de resistencia aeróbica menciona el texto?", "opciones": {"A": "Sentadillas y flexiones de brazos.", "B": "Trotar, caminar rápido o montar bicicleta.", "C": "Saltos con carga máxima.", "D": "Estiramientos de pie."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «intensidad» se refiere a:", "opciones": {"A": "cuánto dura la clase.", "B": "el tamaño de la cancha.", "C": "el número de jugadores.", "D": "qué tan fuerte o exigente es el esfuerzo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto afirma que fuerza y resistencia «se entrenan de manera distinta»?", "opciones": {"A": "Porque son la misma capacidad.", "B": "Porque solo una se usa en el deporte.", "C": "Porque cada una exige un tipo de esfuerzo diferente: cargas cortas frente a esfuerzo continuo.", "D": "Porque la resistencia no necesita descanso."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Durante un trote, un estudiante no puede decir una frase completa sin jadear. ¿Qué debe hacer?", "opciones": {"A": "Bajar el ritmo para reducir la intensidad.", "B": "Subir el ritmo.", "C": "Dejar de respirar profundo.", "D": "Mantener la intensidad sin cambios."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para empezar a trabajar la fuerza con seguridad, conviene:", "opciones": {"A": "cargar el máximo peso desde el inicio.", "B": "omitir los descansos.", "C": "usar el propio peso corporal y cuidar la técnica.", "D": "entrenar sin calentar."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dice que «entre más pesado, mejor» para ganar fuerza. Según el texto, su idea:", "opciones": {"A": "es correcta, porque el peso máximo es lo único que importa.", "B": "no es correcta, porque la carga se aumenta poco a poco con buena técnica y descanso.", "C": "es correcta, porque la técnica no influye.", "D": "no es correcta, porque la fuerza no se entrena."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "Además de correr rápido, ¿qué incluye la velocidad?", "opciones": {"A": "Solo mantener el esfuerzo por mucho tiempo.", "B": "Estirar los músculos.", "C": "Cargar peso.", "D": "Reaccionar a tiempo ante una señal y cambiar de dirección."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuánto tiempo debe mantenerse cada posición de estiramiento?", "opciones": {"A": "Un segundo, con rebotes.", "B": "Cinco minutos.", "C": "Hasta sentir dolor.", "D": "Entre diez y treinta segundos."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la palabra «agilidad» significa:", "opciones": {"A": "fuerza máxima.", "B": "facilidad y rapidez para moverse y cambiar de posición.", "C": "cansancio acumulado.", "D": "calentamiento previo."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué se dejan descansos largos entre las carreras de velocidad?", "opciones": {"A": "Para que el cuerpo se enfríe por completo.", "B": "Para evitar correr.", "C": "Para recuperar energía y que cada repetición sea realmente rápida.", "D": "Para que el entrenamiento dure más."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Antes de un partido, la mejor preparación de la flexibilidad es:", "opciones": {"A": "hacer movimientos dinámicos, como círculos de brazos y balanceos de piernas.", "B": "hacer estiramientos prolongados con rebotes.", "C": "no mover las articulaciones.", "D": "estirar hasta sentir dolor."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "Una estudiante siente dolor al estirar. ¿Qué debe hacer?", "opciones": {"A": "Forzar más hasta que ceda.", "B": "Reducir el estiramiento hasta un punto cómodo, sin dolor.", "C": "Rebotar para ganar amplitud.", "D": "Ignorar la señal del cuerpo."}}, {"n": 14, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué los estiramientos prolongados se dejan para el final?", "opciones": {"A": "Porque los músculos están calientes y se estiran mejor.", "B": "Porque antes de la actividad no hay tiempo.", "C": "Porque reemplazan la vuelta a la calma.", "D": "Porque el calentamiento los prohíbe."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué mide el sit and reach (flexión de tronco sentado)?", "opciones": {"A": "La fuerza de los brazos.", "B": "La velocidad de reacción.", "C": "La resistencia aeróbica.", "D": "La flexibilidad de la espalda baja y de la parte trasera de las piernas."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, una «batería de test» es:", "opciones": {"A": "un aparato eléctrico para medir.", "B": "un descanso entre ejercicios.", "C": "un partido por equipos.", "D": "un conjunto de pruebas aplicadas en una misma jornada."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Para qué sirve el retest?", "opciones": {"A": "Para castigar los malos resultados.", "B": "Para comprobar si el trabajo realizado produjo mejoras.", "C": "Para borrar la primera ficha.", "D": "Para cambiar el reglamento."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Para medir la resistencia muscular del abdomen se usa:", "opciones": {"A": "el salto largo sin impulso.", "B": "la carrera de 30 metros.", "C": "las abdominales en un minuto.", "D": "el sit and reach."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "La frase «una prueba no mide a la persona, sino el estado de una capacidad» significa que:", "opciones": {"A": "un mal resultado hoy no define a la persona y puede mejorar con la práctica.", "B": "quien salta menos no sirve para el deporte.", "C": "solo importa el mejor resultado del curso.", "D": "las pruebas no sirven para nada."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "A partir de las tres lecturas, ¿cómo se relacionan el entrenamiento y los test físicos?", "opciones": {"A": "Los test muestran el estado de cada capacidad, y un entrenamiento adecuado permite mejorarla y comprobarlo con un retest.", "B": "Los test reemplazan al entrenamiento.", "C": "El entrenamiento solo sirve si se evita medir.", "D": "Los test se hacen para dejar fuera a quienes tienen menos fuerza."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g8-p2-quiz1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Capacidades físicas y pruebas que las miden (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Capacidades físicas y pruebas que las miden", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las capacidades físicas básicas son la resistencia, la fuerza, la velocidad y la flexibilidad. Para saber cómo está cada una se usan pruebas físicas, que son ejercicios estandarizados: se hacen siempre con el mismo procedimiento. La resistencia aeróbica se mide con el Course Navette o test de ida y vuelta de 20 metros, en el que se corre entre dos líneas al ritmo de una señal sonora que se acelera. La resistencia muscular del abdomen se mide con las abdominales en un minuto. La fuerza explosiva de las piernas se mide con el salto largo sin impulso, y la velocidad, con una carrera de 50 metros cronometrada.<br><br>Las pruebas no sirven para comparar a unos estudiantes con otros, sino para conocer el punto de partida de cada uno y comprobar su progreso. Para que los resultados sean confiables, se hacen después de un calentamiento, con la técnica correcta y en condiciones similares cada vez."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué prueba mide la resistencia aeróbica?", "opciones": {"A": "El salto largo sin impulso.", "B": "El Course Navette.", "C": "La carrera de 50 metros.", "D": "Las abdominales en un minuto."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué capacidad mide la carrera de 50 metros cronometrada?", "opciones": {"A": "La resistencia aeróbica.", "B": "La flexibilidad.", "C": "La velocidad.", "D": "La fuerza abdominal."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿para qué sirven las pruebas físicas?", "opciones": {"A": "Para conocer el punto de partida y comprobar el progreso de cada estudiante.", "B": "Para clasificar quién es el mejor del curso.", "C": "Para reemplazar la clase.", "D": "Para evitar el calentamiento."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «estandarizadas» significa que las pruebas:", "opciones": {"A": "se hacen sin ninguna regla.", "B": "se realizan siempre con el mismo procedimiento.", "C": "solo las conoce el docente.", "D": "cambian cada día."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la señal sonora del Course Navette se va acelerando?", "opciones": {"A": "Para distraer a los corredores.", "B": "Para que la prueba sea más corta.", "C": "Para evitar que lleguen a la línea.", "D": "Para aumentar la exigencia poco a poco hasta el límite de cada estudiante."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Tras tres meses, un estudiante completa más tramos en el Course Navette. ¿Qué indica esto?", "opciones": {"A": "Que su flexibilidad empeoró.", "B": "Que su velocidad bajó.", "C": "Que su resistencia aeróbica mejoró.", "D": "Que no calentó."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para medir la fuerza explosiva de las piernas se utiliza:", "opciones": {"A": "el salto largo sin impulso.", "B": "el Course Navette.", "C": "la carrera de 50 metros.", "D": "las abdominales en un minuto."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se hace calentamiento antes de las pruebas?", "opciones": {"A": "Para que la prueba dure menos.", "B": "Para que los resultados sean confiables y se evite lesionarse.", "C": "Porque lo exige el reglamento de cada deporte.", "D": "Para recuperarse después."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, las abdominales en un minuto miden:", "opciones": {"A": "la velocidad de reacción.", "B": "la flexibilidad.", "C": "la fuerza de los brazos.", "D": "la resistencia muscular del abdomen."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué idea resume mejor el texto?", "opciones": {"A": "Las pruebas físicas permiten medir cada capacidad y seguir el progreso personal, si se aplican correctamente.", "B": "Las pruebas sirven para comparar a los estudiantes y dejar fuera a los más lentos.", "C": "Las pruebas físicas no necesitan técnica.", "D": "Solo la resistencia se puede medir."}}]}, {"id": "2027-g8-p2-quiz2", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Reglamento de balonmano y microfútbol (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Reglamento de balonmano y microfútbol", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El balonmano se juega con las manos entre dos equipos; en la versión escolar, cada equipo tiene un portero y cinco o seis jugadores de campo. El objetivo es lanzar el balón a la portería contraria. Un jugador puede dar como máximo tres pasos con el balón en las manos y no puede retenerlo más de tres segundos sin moverse. Si bota el balón y lo toma con las dos manos, no puede volver a botarlo: eso se llama doble regate. Solo el portero puede entrar al área de portería. Las faltas graves, como golpear o empujar con violencia, pueden sancionarse con una suspensión de dos minutos fuera del juego. Cuando una falta impide una clara opción de gol, se cobra un lanzamiento de siete metros.<br><br>El microfútbol se juega con los pies en una cancha pequeña, entre equipos de cinco jugadores. Las faltas se sancionan con tiro libre, y la tarjeta amarilla advierte, mientras que la roja expulsa al jugador. En ambos deportes los equipos deben cooperar: pasar, ocupar espacios y comunicarse."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "En balonmano, ¿cuántos pasos como máximo se pueden dar con el balón en las manos?", "opciones": {"A": "Uno.", "B": "Tres.", "C": "Cinco.", "D": "Diez."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Quién puede entrar al área de portería en balonmano?", "opciones": {"A": "Todos los jugadores.", "B": "Solo el portero.", "C": "Solo los defensas.", "D": "El árbitro y los delanteros."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el doble regate consiste en:", "opciones": {"A": "botar el balón, tomarlo con las dos manos y volver a botarlo.", "B": "lanzar dos veces seguidas a la portería.", "C": "pasar el balón a dos compañeros.", "D": "hacer dos saques seguidos."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, una «suspensión» de dos minutos es:", "opciones": {"A": "un premio por buen juego.", "B": "un descanso entre tiempos.", "C": "una salida temporal del juego como sanción.", "D": "un cambio de portero."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué solo el portero puede entrar al área de portería?", "opciones": {"A": "Para que los demás jugadores descansen.", "B": "Para proteger la portería de ataques demasiado cercanos.", "C": "Para hacer el juego más lento.", "D": "Porque los demás no saben jugar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador de balonmano se queda cinco segundos sin moverse con el balón en las manos. ¿Qué falta comete?", "opciones": {"A": "Retener el balón más de tres segundos.", "B": "Doble regate.", "C": "Pasos.", "D": "Ninguna falta."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un partido de microfútbol, un jugador recibe tarjeta roja. ¿Qué significa?", "opciones": {"A": "Que recibe una advertencia.", "B": "Que debe descansar un minuto.", "C": "Que se cobra tiro libre a su favor.", "D": "Que es expulsado del partido."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Con qué parte del cuerpo se juega el microfútbol?", "opciones": {"A": "Con las manos.", "B": "Con raquetas.", "C": "Con palos.", "D": "Con los pies."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se cobra un lanzamiento de siete metros cuando una falta impide una clara opción de gol?", "opciones": {"A": "Porque compensa la oportunidad de gol que perdió el equipo atacante.", "B": "Porque premia la falta.", "C": "Porque termina el partido.", "D": "Porque cambia al portero."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué tienen en común el balonmano y el microfútbol según el texto?", "opciones": {"A": "Se juegan sin árbitro.", "B": "Se juegan solo con las manos.", "C": "Exigen cooperación entre los jugadores y respeto por las reglas.", "D": "No tienen sanciones."}}]}, {"id": "2027-g8-p2-taller", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Resultados de las pruebas físicas (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Course Navette y velocidad de 50 metros", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El Course Navette, también llamado test de Léger, mide la resistencia aeróbica. El estudiante corre de ida y vuelta entre dos líneas separadas 20 metros, al ritmo de una señal sonora que se acelera cada cierto tiempo. En cada cruce debe pisar o sobrepasar la línea antes de la señal siguiente. La prueba termina cuando no logra llegar a la línea a tiempo dos veces seguidas, y se registra el último nivel o tramo alcanzado.<br><br>Para medir la velocidad se usa la carrera de 50 metros con salida de pie, cronometrada por un compañero. Aquí el esfuerzo es máximo, pero muy corto. En la primera prueba, administrar bien el esfuerzo es clave; en la segunda, lo importante es la reacción al salir y mantener la técnica de carrera hasta la meta. Los dos resultados se anotan en una ficha para poder compararlos con la medición final."}, {"id": 2, "titulo": "Fuerza y flexibilidad: la importancia de la técnica", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Las pruebas de fuerza dependen mucho de la técnica. En el salto largo sin impulso, el estudiante se coloca detrás de una línea con los pies separados al ancho de los hombros, flexiona las rodillas, balancea los brazos hacia atrás y salta hacia adelante con ambos pies; se mide desde la línea hasta el talón más cercano. En las abdominales en un minuto, las rodillas van flexionadas, los pies apoyados y las manos cruzadas sobre el pecho; la repetición solo cuenta si el tronco sube hasta tocar los muslos y vuelve a apoyarse en el suelo.<br><br>Si la técnica no es correcta, el resultado no refleja la capacidad real y puede incluso causar molestias. Por eso conviene explicar y demostrar cada prueba antes de aplicarla, y calentar los músculos que se van a usar."}, {"id": 3, "titulo": "De la tabla a la conclusión: analizar mis resultados", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Los datos de las pruebas solo son útiles si se analizan. El primer paso es organizarlos en una tabla: una columna para cada prueba y una fila para la medición inicial y otra para el retest. El segundo paso es graficarlos; un gráfico de barras permite ver de un vistazo en qué prueba hubo más cambio. El tercer paso es interpretar: si el número de tramos del Course Navette aumentó, la resistencia mejoró; si el tiempo de los 50 metros disminuyó, la velocidad mejoró; si la distancia del salto aumentó, la potencia de las piernas mejoró.<br><br>Cuando un resultado no cambia o empeora, se busca la causa: poca práctica, falta de descanso o técnica incorrecta. Finalmente se redactan las conclusiones y se plantea qué se hará distinto en el siguiente periodo. El análisis no busca encontrar culpables, sino tomar decisiones para entrenar mejor."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué capacidad mide el Course Navette?", "opciones": {"A": "La resistencia aeróbica.", "B": "La velocidad.", "C": "La fuerza.", "D": "La flexibilidad."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿A qué distancia están las dos líneas del Course Navette?", "opciones": {"A": "10 metros.", "B": "50 metros.", "C": "20 metros.", "D": "100 metros."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuándo termina la prueba del Course Navette?", "opciones": {"A": "Cuando pasan 12 minutos.", "B": "Cuando el estudiante lo decide.", "C": "Cuando suena la primera señal.", "D": "Cuando no logra llegar a la línea a tiempo dos veces seguidas."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «administrar el esfuerzo» significa:", "opciones": {"A": "gastar toda la energía al inicio.", "B": "evitar hacer ejercicio.", "C": "distribuir la energía de forma adecuada durante la prueba.", "D": "contar los metros recorridos."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la señal del Course Navette se acelera cada cierto tiempo?", "opciones": {"A": "Para que la prueba sea más corta.", "B": "Para aumentar la exigencia hasta el límite de cada estudiante.", "C": "Para confundir a los corredores.", "D": "Para que nadie llegue a la línea."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "En los 50 metros, un estudiante pierde velocidad al final porque cruza los brazos. ¿Qué debe corregir?", "opciones": {"A": "Detenerse antes de la meta.", "B": "Mantener la técnica de carrera hasta la meta.", "C": "Correr más lento todo el recorrido.", "D": "Mirar al piso."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué conviene anotar los resultados en una ficha?", "opciones": {"A": "Porque reemplaza la prueba.", "B": "Porque así se evita repetir la prueba.", "C": "Porque sirve para clasificar a los estudiantes.", "D": "Porque permite compararlos con la medición final y ver el progreso."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Desde dónde se mide el salto largo sin impulso?", "opciones": {"A": "Desde la punta del pie hasta la meta.", "B": "Desde la línea hasta la mano.", "C": "Desde el centro de la cancha.", "D": "Desde la línea hasta el talón más cercano."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Una repetición de abdominales solo cuenta si:", "opciones": {"A": "se hace lo más rápido posible.", "B": "se levantan los pies del suelo.", "C": "el tronco sube hasta tocar los muslos y vuelve a apoyarse en el suelo.", "D": "se usan las manos para impulsarse."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, la palabra «reflejar» significa:", "opciones": {"A": "mostrar o representar fielmente.", "B": "ocultar.", "C": "repetir.", "D": "corregir."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué conviene demostrar cada prueba antes de aplicarla?", "opciones": {"A": "Para que los estudiantes se cansen menos.", "B": "Para que todos la hagan con la técnica correcta y el resultado sea válido.", "C": "Para que el docente no tenga que corregir.", "D": "Para que la prueba sea más rápida."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante hace abdominales impulsándose con las manos. ¿Qué debe corregir?", "opciones": {"A": "Apoyar las manos detrás de la cabeza y tirar.", "B": "Estirar las rodillas.", "C": "Hacerlas con los pies en el aire.", "D": "Mantener las manos cruzadas sobre el pecho."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "En el salto largo sin impulso, ¿qué movimiento ayuda a impulsarse?", "opciones": {"A": "Mantener las piernas rígidas.", "B": "Saltar con un solo pie.", "C": "Flexionar las rodillas y balancear los brazos hacia atrás antes del salto.", "D": "Dejar los brazos pegados al cuerpo."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Dos estudiantes tienen la misma fuerza, pero uno hace mal la técnica. Según el texto, ¿qué pasará con sus resultados?", "opciones": {"A": "Los resultados serán iguales.", "B": "El de mala técnica saltará más lejos.", "C": "El de mala técnica obtendrá un resultado que no refleja su capacidad real.", "D": "La técnica no cambia nada."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué tipo de gráfico se recomienda para comparar las pruebas?", "opciones": {"A": "Un gráfico de barras.", "B": "Un mapa.", "C": "Un dibujo libre.", "D": "Un calendario."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, «interpretar» los datos significa:", "opciones": {"A": "borrarlos.", "B": "explicar qué significan.", "C": "repetirlos.", "D": "copiarlos."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "Si el tiempo de los 50 metros disminuyó, ¿por qué se dice que la velocidad mejoró?", "opciones": {"A": "Porque corrió menos metros.", "B": "Porque recorrió la misma distancia en menos tiempo.", "C": "Porque descansó más.", "D": "Porque cambió de pista."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un estudiante mantuvo el mismo resultado en las abdominales. ¿Qué debe hacer?", "opciones": {"A": "Buscar posibles causas, como poca práctica o técnica incorrecta, y ajustar su trabajo.", "B": "Abandonar la prueba.", "C": "Borrar el resultado.", "D": "Culpar al compañero que anotó."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿para qué se analizan los resultados?", "opciones": {"A": "Para señalar a quien rinde menos.", "B": "Para evitar el retest.", "C": "Para clasificar a los estudiantes.", "D": "Para tomar decisiones y entrenar mejor, no para buscar culpables."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Después de leer las tres lecturas, ¿cuál es el mejor camino para evaluar la condición física?", "opciones": {"A": "Medir con la técnica correcta, organizar los datos en tabla y gráfica, interpretarlos y decidir cómo mejorar.", "B": "Medir una sola vez y compararse con el mejor del curso.", "C": "Anotar solo los mejores resultados.", "D": "Evitar el retest para no desanimarse."}, "textoIds": [1, 2, 3]}]}, {"id": "2027-g9-p2-quiz1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Condición física y frecuencia cardiaca (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Condición física y frecuencia cardiaca", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La condición física es el estado general del cuerpo para realizar esfuerzos y recuperarse bien. Tiene cuatro componentes que se trabajan en la clase: la resistencia, la fuerza funcional (la que se usa en movimientos de la vida diaria y del deporte, como empujar, saltar o levantarse), la velocidad y la flexibilidad.<br><br>Una forma de controlar el esfuerzo es la frecuencia cardiaca, es decir, los latidos del corazón por minuto. Se mide en reposo y durante el ejercicio, tomando el pulso en el cuello o en la muñeca durante 15 segundos y multiplicando por cuatro. La frecuencia cardiaca máxima se estima restando la edad a 220. A partir de ese valor se establecen zonas: entre el 50 % y el 60 % el esfuerzo es muy suave; entre el 60 % y el 70 %, suave, y mejora la resistencia de base; entre el 70 % y el 80 %, moderado; y por encima del 80 %, intenso, y solo se mantiene poco tiempo. Trabajar en la zona adecuada permite mejorar sin exagerar."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuáles son los cuatro componentes de la condición física?", "opciones": {"A": "Resistencia, fuerza funcional, velocidad y flexibilidad.", "B": "Peso, talla, edad y sexo.", "C": "Solo fuerza y velocidad.", "D": "Equilibrio, ritmo, lateralidad y postura."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se estima la frecuencia cardiaca máxima?", "opciones": {"A": "Sumando la edad a 220.", "B": "Multiplicando la edad por 10.", "C": "Dividiendo 220 entre la edad.", "D": "Restando la edad a 220."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Si se toma el pulso durante 15 segundos, ¿por cuánto se multiplica para obtener los latidos por minuto?", "opciones": {"A": "Por dos.", "B": "Por cuatro.", "C": "Por diez.", "D": "Por seis."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «fuerza funcional» es la que:", "opciones": {"A": "se usa en movimientos de la vida diaria y del deporte.", "B": "solo se usa en el gimnasio.", "C": "se mide con el pulso.", "D": "depende de la edad."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué conviene trabajar en la zona de frecuencia cardiaca adecuada?", "opciones": {"A": "Para evitar medir el pulso.", "B": "Para mejorar sin exagerar el esfuerzo.", "C": "Para correr más rápido siempre.", "D": "Para no calentar."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una estudiante de 16 años quiere estimar su frecuencia cardiaca máxima. ¿Cuál es el valor aproximado?", "opciones": {"A": "236 latidos por minuto.", "B": "220 latidos por minuto.", "C": "204 latidos por minuto.", "D": "16 latidos por minuto."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante cuenta 20 latidos en 15 segundos. ¿Cuántos latidos por minuto tiene?", "opciones": {"A": "60.", "B": "35.", "C": "100.", "D": "80."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿a qué tipo de esfuerzo corresponde la zona entre el 70 % y el 80 %?", "opciones": {"A": "Moderado.", "B": "Muy suave.", "C": "Intenso.", "D": "Máximo."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el esfuerzo por encima del 80 % solo se mantiene poco tiempo?", "opciones": {"A": "Porque el reglamento lo prohíbe.", "B": "Porque el pulso se detiene.", "C": "Porque el cuerpo no puede sostener un esfuerzo tan intenso sin fatigarse.", "D": "Porque no hace falta."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "Solo importa la fuerza.", "B": "Controlar la frecuencia cardiaca ayuda a trabajar la condición física con seguridad.", "C": "El pulso no sirve para entrenar.", "D": "Todos deben trabajar al máximo."}}]}, {"id": "2027-g9-p2-quiz2", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Principios del entrenamiento y autocontrol corporal (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Principios del entrenamiento y autocontrol corporal", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Para mejorar la condición física no basta con hacer ejercicio de vez en cuando: el entrenamiento sigue principios. El principio de sobrecarga indica que el cuerpo mejora cuando recibe un esfuerzo algo mayor al habitual; el de progresión, que esa carga debe aumentar de manera gradual; el de continuidad, que se debe entrenar con regularidad, porque si se abandona la práctica los beneficios se pierden; y el de individualidad, que cada persona tiene un punto de partida y una respuesta distinta. También son indispensables el descanso y la recuperación, porque es en ese tiempo cuando el cuerpo se adapta y se fortalece.<br><br>El autocontrol corporal completa el entrenamiento: consiste en respirar de forma rítmica durante el esfuerzo, relajar los músculos al terminar con respiraciones lentas y hacer estiramientos suaves, sin rebotes, para volver a la calma."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Inferencial", "enunciado": "Si un estudiante siempre hace exactamente el mismo esfuerzo, ¿qué es lo más probable?", "opciones": {"A": "Que mejore cada vez más rápido.", "B": "Que su cuerpo deje de mejorar, porque no recibe un estímulo mayor.", "C": "Que no necesite descansar.", "D": "Que gane flexibilidad sin trabajarla."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el principio de progresión indica que la carga debe:", "opciones": {"A": "mantenerse siempre igual.", "B": "subir de golpe.", "C": "aumentar de manera gradual.", "D": "eliminarse."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué sucede si se abandona la práctica?", "opciones": {"A": "Los beneficios aumentan.", "B": "Los beneficios se mantienen para siempre.", "C": "Los beneficios se triplican.", "D": "Los beneficios se pierden."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el principio de «individualidad» significa que:", "opciones": {"A": "todos deben entrenar exactamente igual.", "B": "solo se entrena en equipo.", "C": "se entrena sin descanso.", "D": "cada persona tiene su propio punto de partida y respuesta."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el descanso es indispensable?", "opciones": {"A": "Porque en ese tiempo el cuerpo se adapta y se fortalece.", "B": "Porque reemplaza al ejercicio.", "C": "Porque impide la progresión.", "D": "Porque evita la sobrecarga."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante entrena dos veces al mes y no ve mejoras. ¿Qué principio no está cumpliendo?", "opciones": {"A": "El descanso.", "B": "La continuidad.", "C": "La individualidad.", "D": "La sobrecarga."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una persona trota siempre 10 minutos al mismo ritmo y quiere seguir mejorando. Debe:", "opciones": {"A": "trotar menos cada semana.", "B": "aumentar poco a poco la duración o la intensidad.", "C": "cambiar de deporte cada día.", "D": "suprimir el descanso."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el autocontrol corporal incluye:", "opciones": {"A": "respirar de forma rítmica, relajar los músculos y estirar suavemente.", "B": "entrenar sin descanso.", "C": "evitar la respiración.", "D": "hacer estiramientos con rebotes."}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Después de una sesión intensa, un estudiante se siente agitado. ¿Qué es lo más adecuado?", "opciones": {"A": "Hacer respiraciones lentas y estiramientos suaves para volver a la calma.", "B": "Seguir corriendo a máxima velocidad.", "C": "Dejar de respirar profundo.", "D": "Sentarse sin moverse ni respirar."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "Basta con entrenar al azar.", "B": "El descanso no importa.", "C": "Un entrenamiento eficaz combina principios, descanso y autocontrol corporal.", "D": "Solo importa la intensidad."}}]}, {"id": "2027-g9-p2-taller", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Taller escrito digital — Plan personal de trabajo físico (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Del diagnóstico al objetivo", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El plan personal de trabajo físico dura cuatro semanas y comienza con un diagnóstico: los resultados del test inicial, como el Course Navette, el salto largo, las abdominales en un minuto y la flexibilidad, más una reflexión sobre los hábitos de sueño, alimentación e hidratación. Con esa información, el estudiante elige una capacidad prioritaria y formula un objetivo que sea específico, medible y alcanzable en cuatro semanas, por ejemplo: «aumentar cinco abdominales en un minuto».<br><br>Un objetivo como «ponerme en forma» es demasiado vago, porque no permite saber si se cumplió. También debe ser realista: mejorar poco a poco es más seguro y motivante que proponerse cambios enormes. Finalmente se define cómo se comprobará el avance: con el mismo test al final del plan."}, {"id": 2, "titulo": "Estructura de la semana y de la sesión", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Con el objetivo definido se organiza la semana. Un plan para estudiantes de bachillerato suele incluir tres o cuatro sesiones semanales, alternando días de trabajo con días de descanso para que el cuerpo se recupere. Cada sesión tiene tres partes: el calentamiento, de unos diez minutos, con movilidad articular y ejercicios suaves; la parte principal, donde se trabaja la capacidad elegida con circuitos, carrera continua o intervalos; y la vuelta a la calma, con respiración lenta y estiramientos.<br><br>La carga se aumenta gradualmente: por ejemplo, la semana uno puede tener menos repeticiones o menos minutos que la semana cuatro. Los principios de continuidad y progresión se cumplen cuando se respeta el calendario y se sube la carga poco a poco. Si un día hay dolor, mareo o cansancio extremo, la sesión se suspende o se reduce."}, {"id": 3, "titulo": "Autocontrol, registro y sustentación", "instruccion": "(Responda las preguntas 15 a 19 con base en el siguiente texto; la pregunta 20 se responde con las tres lecturas.)", "cuerpo": "Durante las cuatro semanas, cada sesión se anota en una bitácora: la fecha, el ejercicio, la duración, la frecuencia cardiaca o la percepción del esfuerzo, y cómo se sintió la persona. La bitácora permite ver si se cumple el calendario y detectar señales de alerta. El autocontrol corporal también incluye técnicas de relajación, como la respiración lenta —inhalar por la nariz, sostener un momento y soltar el aire por la boca— y estiramientos suaves al terminar.<br><br>Al final del plan se repite el test inicial, el retest, y se compara con el diagnóstico. En la sustentación, el estudiante presenta su objetivo, muestra sus datos y explica si logró la meta, qué factores ayudaron o dificultaron el proceso y qué haría distinto. Una buena sustentación se apoya en datos, no solo en opiniones."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto dura el plan personal de trabajo físico?", "opciones": {"A": "Cuatro semanas.", "B": "Dos semanas.", "C": "Un año.", "D": "Un día."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿con qué comienza el plan?", "opciones": {"A": "Con una competencia.", "B": "Con un diagnóstico basado en el test inicial y los hábitos.", "C": "Con el retest.", "D": "Con la sustentación."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, un objetivo «específico» es el que:", "opciones": {"A": "es muy general.", "B": "no se puede medir.", "C": "cambia cada día.", "D": "está bien definido y no deja dudas."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué «ponerme en forma» no es un buen objetivo?", "opciones": {"A": "Porque es demasiado fácil.", "B": "Porque es vago y no permite saber si se cumplió.", "C": "Porque está prohibido.", "D": "Porque requiere un gimnasio."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál de estos es un objetivo bien formulado?", "opciones": {"A": "Ser el mejor del colegio algún día.", "B": "Hacer ejercicio cuando haya ganas.", "C": "Aumentar cinco abdominales en un minuto en cuatro semanas.", "D": "Ponerme en forma pronto."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cómo puede comprobar el estudiante si logró su objetivo?", "opciones": {"A": "Preguntando a un amigo.", "B": "Repitiendo el mismo test al final del plan.", "C": "Esperando a sentirse mejor.", "D": "No es necesario comprobarlo."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿por qué es mejor mejorar poco a poco?", "opciones": {"A": "Porque se avanza menos y no se necesita descanso.", "B": "Porque es más seguro y motivante.", "C": "Porque evita registrar datos.", "D": "Porque así no hay objetivos."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántas sesiones semanales suele incluir el plan?", "opciones": {"A": "Tres o cuatro.", "B": "Una.", "C": "Siete.", "D": "Diez."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuáles son las tres partes de cada sesión?", "opciones": {"A": "Saque, remate y bloqueo.", "B": "Diagnóstico, objetivo y sustentación.", "C": "Test, retest y bitácora.", "D": "Calentamiento, parte principal y vuelta a la calma."}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, aumentar la carga «gradualmente» significa:", "opciones": {"A": "de un solo golpe.", "B": "solo al final.", "C": "poco a poco.", "D": "nunca."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la semana uno puede tener menos carga que la semana cuatro?", "opciones": {"A": "Porque la semana uno no se entrena.", "B": "Porque la carga debe aumentar de forma progresiva.", "C": "Porque se pierde la condición.", "D": "Porque la semana cuatro es de descanso total."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante siente mareo en medio de la sesión. ¿Qué debe hacer?", "opciones": {"A": "Suspender o reducir la sesión.", "B": "Seguir con más intensidad.", "C": "Ignorar la señal.", "D": "Terminar corriendo."}}, {"n": 13, "seccion": 2, "competencia": "Aplicación", "enunciado": "En la semana uno un estudiante trota 10 minutos. ¿Qué es coherente para la semana cuatro?", "opciones": {"A": "60 minutos de golpe.", "B": "Los mismos 10 minutos sin cambio.", "C": "No trotar.", "D": "Unos 16 minutos, subiendo poco a poco."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dice que un plan sin días de descanso mejora más rápido. Según el texto:", "opciones": {"A": "no es correcto, porque el descanso permite que el cuerpo se recupere y es parte del plan.", "B": "es correcto, porque el descanso estorba.", "C": "es correcto si se entrena el doble.", "D": "no es correcto, porque los planes no tienen estructura."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué se anota en la bitácora de cada sesión?", "opciones": {"A": "Solo la nota final.", "B": "Únicamente el nombre del docente.", "C": "El resultado de los demás compañeros.", "D": "La fecha, el ejercicio, la duración, el esfuerzo y cómo se sintió la persona."}}, {"n": 16, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, la «sustentación» es:", "opciones": {"A": "un descanso al final del plan.", "B": "una prueba de velocidad.", "C": "la presentación y explicación del plan con datos y argumentos.", "D": "un registro de convivencia."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué se repite el test inicial al final del plan?", "opciones": {"A": "Para comparar con el diagnóstico y saber si hubo mejora.", "B": "Para castigar los resultados bajos.", "C": "Para cambiar el objetivo.", "D": "Para eliminar la bitácora."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Una estudiante no logró su meta. ¿Qué debe hacer en la sustentación?", "opciones": {"A": "Ocultar los resultados.", "B": "Culpar al docente.", "C": "Explicar con datos qué factores influyeron y qué haría distinto.", "D": "No presentarse."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué una buena sustentación debe apoyarse en datos?", "opciones": {"A": "Porque los datos son decorativos.", "B": "Porque así se evita explicar.", "C": "Porque las opiniones están prohibidas.", "D": "Porque permite evaluar el progreso con evidencia y no solo con opiniones."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Considerando las tres lecturas, un plan personal de trabajo físico bien hecho:", "opciones": {"A": "se improvisa cada día según el ánimo.", "B": "evita el retest para no comparar.", "C": "parte de un diagnóstico, organiza la carga con descansos, se registra y se evalúa al final con datos.", "D": "prescinde de la relajación y del descanso."}, "textoIds": [1, 2, 3]}]}];
